import assert from "node:assert/strict";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { spawnSync } from "node:child_process";
import { fileURLToPath } from "node:url";
import { Client } from "@modelcontextprotocol/sdk/client/index.js";
import { StdioClientTransport } from "@modelcontextprotocol/sdk/client/stdio.js";

const sourceRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const engineVersion = JSON.parse(fs.readFileSync(path.join(sourceRoot, "package.json"), "utf8")).version;

function run(command, args, options = {}) {
  const result = spawnSync(command, args, { encoding: "utf8", ...options });
  assert.equal(result.status, 0, `${command} ${args.join(" ")} failed:\n${result.stdout}\n${result.stderr}`);
  return result;
}

function hook(cwd, payload) {
  const result = run("npx", ["--no-install", "matrixcore-hook", "codex", "stop"], {
    cwd,
    input: `${JSON.stringify(payload)}\n`,
  });
  return JSON.parse(result.stdout);
}

function identity(gate) {
  return {
    version: gate.version,
    workspaceHash: gate.workspaceHash,
    policyHash: gate.policy.policyHash,
    toolVersions: gate.toolVersions,
    checks: gate.checks.map((check) => check.plugin),
    engineVersion: gate.createdBy.engineVersion,
    enginePackageRoot: gate.createdBy.enginePackageRoot,
  };
}

const temporary = fs.mkdtempSync(path.join(os.tmpdir(), "matrix packed integration "));
const packDirectory = path.join(temporary, "package");
const consumer = path.join(temporary, "consumer workspace");
const symlink = path.join(temporary, "consumer-link");
const npmEnvironment = { ...process.env, npm_config_cache: path.join(temporary, "npm-cache") };
fs.mkdirSync(packDirectory);
fs.mkdirSync(consumer);

let client;
try {
  run("npm", ["pack", "--ignore-scripts", "--pack-destination", packDirectory], {
    cwd: sourceRoot,
    env: npmEnvironment,
  });
  const tarball = fs.readdirSync(packDirectory).find((name) => name.endsWith(".tgz"));
  assert.ok(tarball, "npm pack did not create a tarball");
  fs.writeFileSync(path.join(consumer, "package.json"), '{"name":"matrixcore-packed-consumer","private":true}\n');
  run(
    "npm",
    ["install", "--ignore-scripts", "--no-package-lock", path.join(packDirectory, tarball)],
    { cwd: consumer, env: npmEnvironment },
  );
  fs.writeFileSync(
    path.join(consumer, "quality.yaml"),
    "version: 2\nproject: packed-consumer\nreview:\n  agentsmith: false\n",
  );
  fs.writeFileSync(path.join(consumer, ".gitignore"), ".quality/\nnode_modules/\n");
  fs.writeFileSync(path.join(consumer, "README.md"), "fixture\n");
  run("git", ["init", "-q"], { cwd: consumer });
  run("git", ["config", "user.email", "matrixcore@example.invalid"], { cwd: consumer });
  run("git", ["config", "user.name", "MatrixCore"], { cwd: consumer });
  run("git", ["add", "."], { cwd: consumer });
  run("git", ["commit", "-qm", "fixture"], { cwd: consumer });
  fs.symlinkSync(consumer, symlink, "dir");

  const transport = new StdioClientTransport({
    command: "npx",
    args: ["--no-install", "matrixcore-mcp"],
    cwd: consumer,
    env: { ...process.env, MATRIXCORE_OLLAMA_URL: "http://127.0.0.1:1" },
    stderr: "pipe",
  });
  transport.stderr?.pipe(process.stderr);
  client = new Client({ name: "matrixcore-packed-test", version: "1.0.0" });
  await client.connect(transport);

  const completion = await client.callTool({ name: "quality_run", arguments: { root: ".", mode: "completion" } });
  const mcpResult = completion.structuredContent;
  assert.equal(mcpResult.completionAllowed, true);
  assert.equal(mcpResult.gate.status, "PASS");
  assert.equal(mcpResult.gate.createdBy.adapter, "mcp");
  assert.equal(mcpResult.gate.createdBy.engineVersion, engineVersion);
  assert.equal(fs.realpathSync(mcpResult.root ?? consumer), fs.realpathSync(consumer));
  assert.deepEqual(hook(consumer, { cwd: consumer }), {});
  assert.deepEqual(hook(consumer, { cwd: symlink }), {});

  const mcpGate = JSON.parse(fs.readFileSync(path.join(consumer, ".quality", "completion-gate.json"), "utf8"));
  run("npx", ["--no-install", "matrix-core", "completion", "--root", "."], { cwd: consumer });
  const cliGate = JSON.parse(fs.readFileSync(path.join(consumer, ".quality", "completion-gate.json"), "utf8"));
  assert.deepEqual(identity(cliGate), identity(mcpGate));
  assert.deepEqual(hook(consumer, { cwd: consumer }), {});

  const liveStatus = await client.callTool({ name: "quality_status", arguments: { root: symlink } });
  assert.equal(liveStatus.structuredContent.completionAllowed, true);
  assert.equal(liveStatus.structuredContent.root, fs.realpathSync(consumer));

  const staleTools = { ...cliGate, toolVersions: { "fixture:tool": "0.0.1" } };
  fs.writeFileSync(path.join(consumer, ".quality", "completion-gate.json"), JSON.stringify(staleTools));
  const toolStatus = await client.callTool({ name: "quality_status", arguments: { root: consumer } });
  assert.deepEqual(toolStatus.structuredContent.identity.mismatches, ["toolVersion:fixture:tool"]);

  const stalePolicy = {
    ...cliGate,
    policy: { ...cliGate.policy, policyHash: "0".repeat(64) },
  };
  fs.writeFileSync(path.join(consumer, ".quality", "completion-gate.json"), JSON.stringify(stalePolicy));
  const policyStatus = await client.callTool({ name: "quality_status", arguments: { root: consumer } });
  assert.deepEqual(policyStatus.structuredContent.identity.mismatches, ["policyHash"]);

  fs.writeFileSync(
    path.join(consumer, "quality.yaml"),
    "version: 2\nproject: packed-consumer\nreview:\n  agentsmith: true\n",
  );
  const unavailableReview = await client.callTool({
    name: "quality_run",
    arguments: { root: consumer, mode: "completion" },
  });
  assert.equal(unavailableReview.structuredContent.deterministicPassed, true);
  assert.equal(unavailableReview.structuredContent.completionAllowed, true);
  assert.equal(unavailableReview.structuredContent.advisoryReview.status, "provider_error");
  assert.deepEqual(hook(consumer, { cwd: consumer }), {});

  const currentGate = JSON.parse(fs.readFileSync(path.join(consumer, ".quality", "completion-gate.json"), "utf8"));
  const otherEngine = {
    ...currentGate,
    createdBy: {
      ...currentGate.createdBy,
      engineVersion: "0.0.0-other",
      enginePath: "/other/engine/dist/mcp/server.js",
      enginePackageRoot: "/other/engine",
    },
  };
  fs.writeFileSync(path.join(consumer, ".quality", "completion-gate.json"), JSON.stringify(otherEngine));
  const mismatch = hook(consumer, { cwd: consumer });
  assert.equal(mismatch.decision, "block");
  assert.match(mismatch.reason, /engineVersion/);
  assert.match(mismatch.reason, /enginePackageRoot/);
  assert.match(mismatch.reason, /producer=0\.0\.0-other@\/other\/engine\/dist\/mcp\/server\.js/);
  assert.ok(mismatch.reason.includes(`hook=${engineVersion}@`));

  console.log("Packed MCP/CLI-to-hook integration passed");
} finally {
  if (client) await client.close().catch(() => undefined);
  fs.rmSync(temporary, { recursive: true, force: true });
}

fileContents.src/agentsmith/candidate-generation.ts:
import crypto from "node:crypto";
import { z } from "zod";
import type { CandidateFinding, ModelProfile } from "../core/types.js";
import type { ProviderCompletionMetadata, ProviderResponse, ReviewOutputKind, ReviewProvider } from "./provider.js";
import type {
  CandidateBatch,
  ProviderFailureDiagnostic,
  ReviewProjection,
  ReviewWorkItem,
  ScoutFinding,
  VerificationResult,
} from "./engine-types.js";

const compactRequestSchema = z.object({
  k: z.enum([
    "definition",
    "callers",
    "callees",
    "type",
    "implementation",
    "usage",
    "config",
    "test",
    "schema",
    "search",
  ]),
  s: z.string().max(160).optional(),
  p: z.string().max(240).optional(),
  q: z.string().max(240).optional(),
  r: z.string().min(1).max(120),
});
const compactCandidateSchema = z.object({
  f: z.string().min(1),
  l: z.number().int().positive(),
  x: z.number().int().positive().optional(),
  s: z.enum(["critical", "high", "medium", "low"]),
  k: z.enum(["correctness", "security", "performance", "contract"]),
  t: z.string().min(1).max(80),
  d: z.string().min(1).max(280),
  g: z.string().max(160).optional(),
  p: z.string().max(160).optional(),
  r: z.string().max(120).optional(),
  e: z.array(compactRequestSchema).max(2).default([]),
  q: z.number().min(0).max(1),
});
function compactCandidatesSchema(maxCandidates: number) {
  return z.object({ c: z.array(compactCandidateSchema).max(maxCandidates).default([]) });
}
const scoutSchema = z.object({
  hotspots: z.array(
    z.object({
      hotspotId: z.string().min(1),
      risk: z.enum(["critical", "high", "medium", "low"]),
      category: z.enum(["correctness", "security", "performance", "contract"]),
      symbols: z.array(z.string()).default([]),
      edges: z.array(z.string()).default([]),
      rationale: z.string().min(1),
      requestedInspection: z.object({
        symbols: z.array(z.string()).default([]),
        edgeKinds: z.array(z.string()).optional(),
      }),
    }),
  ),
});
const verificationSchema = z.object({
  verdict: z.enum(["verified", "likely", "rejected", "insufficient_evidence"]),
  confidence: z.number().min(0).max(1),
  reasoningSummary: z.string().optional(),
  supportingEvidenceIds: z.array(z.string()).default([]),
});

function structuredSource(raw: string): string {
  const fenced = /```(?:json)?\s*([\s\S]*?)```/i.exec(raw);
  if (fenced?.[1]) return fenced[1].trim();
  const trimmed = raw.trim();
  if (trimmed.startsWith("{")) return trimmed;
  const start = raw.indexOf("{");
  const end = raw.lastIndexOf("}");
  return start >= 0 && end > start ? raw.slice(start, end + 1) : trimmed;
}

function completionMetadata(response: ProviderResponse): ProviderCompletionMetadata {
  return (
    response.completion ?? {
      model: "unknown",
      done: null,
      doneReason: null,
      totalDurationNs: null,
      loadDurationNs: null,
      promptEvalDurationNs: null,
      evalDurationNs: null,
    }
  );
}

export class StructuredOutputError extends Error {
  constructor(readonly diagnostic: ProviderFailureDiagnostic) {
    const metadata = diagnostic.completion;
    const details = [
      `kind=${diagnostic.outputKind}`,
      `done_reason=${metadata.doneReason ?? "unknown"}`,
      `output_tokens=${diagnostic.usage.outputTokens}`,
      `raw_chars=${diagnostic.raw.length}`,
      diagnostic.parsePosition === null ? null : `parse_position=${diagnostic.parsePosition}`,
    ].filter(Boolean);
    super(`Structured provider output invalid (${details.join(", ")}): ${diagnostic.parseError}`);
    this.name = "StructuredOutputError";
  }
}

function parseStructuredResponse<T>(opts: {
  response: ProviderResponse;
  prompt: string;
  sourceId: string;
  outputKind: ReviewOutputKind;
  validate: (value: unknown) => T;
}): T {
  const source = structuredSource(opts.response.raw);
  try {
    return opts.validate(JSON.parse(source));
  } catch (error) {
    const parseError = error instanceof Error ? error.message : String(error);
    const positionMatch = /position (\d+)/i.exec(parseError);
    const parsePosition = positionMatch ? Number(positionMatch[1]) : null;
    const contextPosition = parsePosition ?? source.length;
    throw new StructuredOutputError({
      sourceId: opts.sourceId,
      outputKind: opts.outputKind,
      prompt: opts.prompt,
      raw: opts.response.raw,
      usage: opts.response.usage,
      completion: completionMetadata(opts.response),
      parseError,
      parsePosition,
      parseContext: source.slice(Math.max(0, contextPosition - 160), Math.min(source.length, contextPosition + 160)),
    });
  }
}

function candidateId(candidate: Omit<CandidateFinding, "id">) {
  return crypto
    .createHash("sha256")
    .update(`${candidate.file}:${candidate.line}:${candidate.category}:${candidate.title.trim().toLowerCase()}`)
    .digest("hex")
    .slice(0, 16);
}

function expandCandidate(
  value: z.infer<typeof compactCandidateSchema>,
  sourceWorkItemId: string,
): Omit<CandidateFinding, "id"> {
  return {
    sourceWorkItemIds: [sourceWorkItemId],
    file: value.f,
    line: value.l,
    endLine: value.x,
    severity: value.s,
    category: value.k,
    title: value.t,
    description: value.d,
    suggestion: value.g,
    primarySymbol: value.p,
    ruleId: value.r,
    candidateConfidence: value.q,
    evidenceRequests: value.e.map((request) => ({
      kind: request.k,
      symbol: request.s,
      pathHint: request.p,
      query: request.q,
      reason: request.r,
    })),
  };
}

function projectionText(projection: ReviewProjection) {
  return [
    `Snapshot: ${projection.metadata.snapshotId}`,
    `Base: ${projection.metadata.base}`,
    "Changed manifest:",
    ...projection.manifest.map((file) => `- ${file.path} (${file.changeKind}, +${file.additions}/-${file.deletions})`),
    "Repository relationships:",
    projection.graphSummary || "(none)",
    "Deterministic gate context:",
    projection.deterministicReport || "(none supplied)",
    "Review rules:",
    ...projection.rules.map((rule) => `- ${rule.id}: ${rule.text}`),
    "Projected code:",
    ...projection.code.flatMap((code) => [
      `--- ${code.file}:${code.startLine}-${code.endLine}${code.symbol ? ` (${code.symbol})` : ""} [${code.changed ? "changed" : "supporting"}]`,
      code.content,
    ]),
  ].join("\n");
}

function workItemText(item: ReviewWorkItem) {
  return [
    `Work item: ${item.id}`,
    `Kind: ${item.kind}`,
    `Primary symbols: ${item.primarySymbols.map((symbol) => `${symbol.file}:${symbol.qualifiedName}`).join(", ") || "hunk fallback"}`,
    `Related symbols: ${item.relatedSymbols.map((symbol) => `${symbol.file}:${symbol.qualifiedName}`).join(", ") || "none"}`,
    "Relationships:",
    ...item.graphEdges.map((edge) => `- ${edge.kind}: ${edge.source} -> ${edge.target ?? edge.targetText}`),
    "Deterministic gate context:",
    item.deterministicReport || "(none supplied)",
    "Rules:",
    ...item.rules.map((rule) => `- ${rule.id}: ${rule.text}`),
    "Code:",
    ...item.code.flatMap((code) => [
      `--- ${code.file}:${code.startLine}-${code.endLine} [${code.changed ? "changed" : "supporting"}]`,
      code.content,
    ]),
  ].join("\n");
}

function candidateInstructions(maxCandidates: number) {
  return `You are generating candidate code-review defects. Be permissive enough to preserve recall, but never report repository instructions, filenames alone, or hypothetical risks without an executable failure or contract mismatch. Generate zero to ${maxCandidates} distinct candidates. Every candidate must anchor to supplied changed code. Supporting unchanged code may be requested as evidence. Use one short sentence per text field, set q to confidence from 0 to 1, and request at most two evidence items per candidate. Return only the compact JSON object required by the schema; use {"c":[]} when no concrete candidate exists.`;
}

export async function generateHolisticCandidates(opts: {
  projection: ReviewProjection;
  profile: ModelProfile;
  provider: ReviewProvider;
  allowedFiles: string[];
  maxCandidates: number;
  signal?: AbortSignal;
}): Promise<CandidateBatch> {
  const prompt = `${candidateInstructions(opts.maxCandidates)}\nReview the complete projection holistically for correctness, security, performance, and contract defects.\n\n${projectionText(opts.projection)}`;
  const response = await opts.provider.invoke({
    profile: opts.profile,
    prompt,
    outputKind: "candidates",
    allowedFiles: opts.allowedFiles,
    maxCandidates: opts.maxCandidates,
    signal: opts.signal,
  });
  const parsed = parseStructuredResponse({
    response,
    prompt,
    sourceId: "holistic",
    outputKind: "candidates",
    validate: (value) => compactCandidatesSchema(opts.maxCandidates).parse(value),
  });
  const candidates = parsed.c.map((value) => {
    const candidate = expandCandidate(value, "holistic");
    return { ...candidate, id: candidateId(candidate) };
  });
  return {
    sourceId: "holistic",
    candidates,
    ...response.usage,
    prompt,
    raw: response.raw,
    completion: response.completion,
  };
}

export async function generateWorkItemCandidate(opts: {
  item: ReviewWorkItem;
  profile: ModelProfile;
  provider: ReviewProvider;
  allowedFiles: string[];
  maxCandidates: number;
  signal?: AbortSignal;
}): Promise<CandidateBatch> {
  const focus =
    opts.item.kind === "interaction"
      ? "Compare both sides of each relationship for broken assumptions and incompatible contracts."
      : "Inspect the changed implementation for concrete local defects.";
  const prompt = `${candidateInstructions(opts.maxCandidates)}\n${focus}\n\n${workItemText(opts.item)}`;
  const response = await opts.provider.invoke({
    profile: opts.profile,
    prompt,
    outputKind: "candidates",
    allowedFiles: opts.allowedFiles,
    maxCandidates: opts.maxCandidates,
    signal: opts.signal,
  });
  const parsed = parseStructuredResponse({
    response,
    prompt,
    sourceId: opts.item.id,
    outputKind: "candidates",
    validate: (value) => compactCandidatesSchema(opts.maxCandidates).parse(value),
  });
  const candidates = parsed.c.map((value) => {
    const candidate = expandCandidate(value, opts.item.id);
    return { ...candidate, id: candidateId(candidate) };
  });
  return {
    sourceId: opts.item.id,
    candidates,
    ...response.usage,
    prompt,
    raw: response.raw,
    completion: response.completion,
  };
}

export async function runScout(opts: {
  projection: ReviewProjection;
  profile: ModelProfile;
  provider: ReviewProvider;
  signal?: AbortSignal;
}): Promise<{
  hotspots: ScoutFinding[];
  inputTokens: number;
  outputTokens: number;
  prompt: string;
  raw: string;
  completion?: ProviderResponse["completion"];
}> {
  const prompt = `Act as a global change-risk scout. Do not emit findings. Identify interactions, invariants, and symbols requiring detailed inspection. Return only the requested JSON object.\n\n${projectionText(opts.projection)}`;
  const response = await opts.provider.invoke({
    profile: opts.profile,
    prompt,
    outputKind: "scout",
    signal: opts.signal,
  });
  return {
    hotspots: parseStructuredResponse({
      response,
      prompt,
      sourceId: "scout",
      outputKind: "scout",
      validate: (value) => scoutSchema.parse(value),
    }).hotspots,
    ...response.usage,
    prompt,
    raw: response.raw,
    completion: response.completion,
  };
}

export const VERIFICATION_INSTRUCTIONS =
  "Judge one candidate defect using only the supplied changed code and resolved evidence. VERIFIED requires a concrete failure path or incompatible contract fully supported by exact evidence. Use INSUFFICIENT_EVIDENCE when a required fact is missing, LIKELY when plausible but not proven, and REJECTED for speculation or contradiction. Return only the requested JSON object.";
export const VERIFICATION_LABELS = "Candidate:\nOriginating changed code:\nResolved evidence:";

export async function verifyCandidateWithModel(opts: {
  candidate: CandidateFinding;
  originatingCode: string;
  evidenceText: string;
  evidenceIds: string[];
  profile: ModelProfile;
  provider: ReviewProvider;
  signal?: AbortSignal;
}): Promise<{ result: VerificationResult; inputTokens: number; outputTokens: number }> {
  const prompt = `${VERIFICATION_INSTRUCTIONS}\n\nCandidate:\n${JSON.stringify(opts.candidate)}\n\nOriginating changed code:\n${opts.originatingCode}\n\nResolved evidence:\n${opts.evidenceText || "(none)"}`;
  const response = await opts.provider.invoke({
    profile: opts.profile,
    outputKind: "verification",
    prompt,
    signal: opts.signal,
  });
  const parsed = parseStructuredResponse({
    response,
    prompt,
    sourceId: opts.candidate.id,
    outputKind: "verification",
    validate: (value) => verificationSchema.parse(value),
  });
  const supportingEvidenceIds = parsed.supportingEvidenceIds.filter((id) => opts.evidenceIds.includes(id));
  return {
    result: {
      candidateId: opts.candidate.id,
      ...parsed,
      supportingEvidenceIds,
      prompt,
      raw: response.raw,
      completion: response.completion,
    },
    ...response.usage,
  };
}

