import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { afterEach, describe, expect, it } from "vitest";
import {
  isAgentSmithTraceEnabled,
  listAgentSmithTraces,
  pruneAgentSmithTraces,
  readAgentSmithTrace,
