function ratio(numerator: number, denominator: number): number | null {
  return denominator > 0 ? numerator / denominator : null;
}

function changedLineRanges(diff: string): Map<string, Array<{ start: number; end: number }>> {
  const ranges = new Map<string, Array<{ start: number; end: number }>>();
  let file = "";
  for (const line of diff.split("\n")) {
    if (line.startsWith("+++ b/")) {
      file = line.slice(6);
      continue;
    }
    if (!file || !line.startsWith("@@")) continue;
    const match = /\+(\d+)(?:,(\d+))?/.exec(line);
    if (!match) continue;
    const start = Number(match[1]);
    const count = match[2] === undefined ? 1 : Number(match[2]);
    if (count <= 0) continue;
    const values = ranges.get(file) ?? [];
    values.push({ start, end: start + count - 1 });
    ranges.set(file, values);
  }
  return ranges;
}

function reviewedChangedLines(scope: ReviewScope, workItems: ReviewWorkItem[]) {
  const ranges = changedLineRanges(scope.diff);
  const eligible = new Set<string>();
  const reviewed = new Set<string>();
  for (const [file, fileRanges] of ranges)
    for (const range of fileRanges)
      for (let line = range.start; line <= range.end; line += 1) eligible.add(`${file}:${line}`);
  for (const item of workItems)
    for (const snippet of item.code) {
      const fileRanges = ranges.get(snippet.file) ?? [];
      for (const range of fileRanges) {
        const start = Math.max(range.start, snippet.startLine);
        const end = Math.min(range.end, snippet.endLine);
        for (let line = start; line <= end; line += 1) reviewed.add(`${snippet.file}:${line}`);
      }
    }
  return { eligible: eligible.size, reviewed: reviewed.size };
}

function evidenceMetrics(execution: EngineExecution) {
  let requests = 0;
  let validRequests = 0;
  let resolvedRecords = 0;
  let relevantRecords = 0;
  for (const candidate of execution.candidates) {
    requests += candidate.evidenceRequests.length;
    validRequests += candidate.evidenceRequests.filter((request) =>
      Boolean(request.symbol || request.pathHint || request.query),
    ).length;
    const records = (execution.evidence[candidate.id] ?? []).slice(1);
    resolvedRecords += records.length;
    for (const record of records) {
      const relevant = candidate.evidenceRequests.some((request) => {
        const pathMatches = request.pathHint
          ? record.file === request.pathHint || record.file.includes(request.pathHint)
          : false;
        const symbolMatches = request.symbol
          ? record.symbol === request.symbol || record.symbol?.endsWith(`:${request.symbol}`)
          : false;
        const queryMatches = request.query ? record.snippet.includes(request.query) : false;
        return pathMatches || symbolMatches || queryMatches;
      });
      if (relevant) relevantRecords += 1;
    }
  }
  return {
    requests,
    validRequests,
    requestValidityRate: ratio(validRequests, requests),
    resolvedRecords,
    relevantRecords,
    relevanceRate: ratio(relevantRecords, resolvedRecords),
    unsupportedResolvedRecords: resolvedRecords - relevantRecords,
  };
}

export function collectEvalMetrics(opts: {
  scope: ReviewScope;
  result: ReviewResult;
  execution: EngineExecution;
  durationMs: number;
}) {
  const { scope, result, execution } = opts;
  const coverage = result.coverage;
  const changedLines = reviewedChangedLines(scope, execution.workItems);
  const workOmissions = coverage.omissions.filter((item) => item.kind === "work-item");
  const candidateOmissions = coverage.omissions.filter((item) => item.kind === "candidate");
  const uniqueWorkIds = new Set([
    ...execution.workItems.map((item) => item.id),
    ...workOmissions.map((item) => item.id),
  ]);
  const duplicateWorkItemRows = execution.workItems.length + workOmissions.length - uniqueWorkIds.size;
  const adjudicatedIds = new Set(execution.verification.map((item) => item.candidateId));
  const modelAdjudicated = execution.verification.filter((item) => item.cacheStatus !== undefined).length;
  const omittedIds = new Set(candidateOmissions.map((item) => item.id));
  const omittedHighSeverity = execution.candidates.filter(
    (candidate) => omittedIds.has(candidate.id) && ["critical", "high"].includes(candidate.severity),
  ).length;
  const evidence = evidenceMetrics(execution);
  const eligibleWorkItems = coverage.localUnitsGenerated + coverage.interactionUnitsGenerated;
  const reviewedWorkItems = coverage.localUnitsReviewed + coverage.interactionUnitsReviewed;
  const honesty = {
    clearWithUnreviewedFiles: result.outcome === "clear" && coverage.changedFilesReviewed < coverage.changedFiles,
    completedWithCandidateOmissions: result.status === "completed" && candidateOmissions.length > 0,
    zeroGapsWithUnsupportedEvidence: coverage.evidenceGaps === 0 && evidence.unsupportedResolvedRecords > 0,
    duplicateWorkItemRows,
    honest:
      !(result.outcome === "clear" && coverage.changedFilesReviewed < coverage.changedFiles) &&
      !(result.status === "completed" && candidateOmissions.length > 0) &&
      !(coverage.evidenceGaps === 0 && evidence.unsupportedResolvedRecords > 0) &&
      duplicateWorkItemRows === 0,
  };
  return {
    coverage: {
      changedFiles: {
        reviewed: coverage.changedFilesReviewed,
        eligible: coverage.changedFiles,
        rate: ratio(coverage.changedFilesReviewed, coverage.changedFiles),
      },
      changedSymbols: {
        reviewed: coverage.changedSymbolsReviewed,
        eligible: coverage.changedSymbols,
        rate: ratio(coverage.changedSymbolsReviewed, coverage.changedSymbols),
      },
      changedLines: { ...changedLines, rate: ratio(changedLines.reviewed, changedLines.eligible) },
      localUnits: {
        reviewed: coverage.localUnitsReviewed,
        eligible: coverage.localUnitsGenerated,
        rate: ratio(coverage.localUnitsReviewed, coverage.localUnitsGenerated),
      },
      interactionUnits: {
        reviewed: coverage.interactionUnitsReviewed,
        eligible: coverage.interactionUnitsGenerated,
        rate: ratio(coverage.interactionUnitsReviewed, coverage.interactionUnitsGenerated),
      },
      workItems: {
        reviewed: reviewedWorkItems,
        eligible: eligibleWorkItems,
        unique: uniqueWorkIds.size,
        duplicateRows: duplicateWorkItemRows,
        rate: ratio(reviewedWorkItems, eligibleWorkItems),
      },
      globalScan: coverage.globalScan,
    },
    candidates: {
      generated: execution.candidates.length,
      adjudicated: adjudicatedIds.size,
      modelAdjudicated,
      omitted: candidateOmissions.length,
      omittedHighSeverity,
      adjudicationRate: ratio(adjudicatedIds.size, execution.candidates.length),
      modelAdjudicationRate: ratio(modelAdjudicated, execution.candidates.length),
    },
    evidence,
    reliability: {
      callsStarted: coverage.callsStarted ?? 0,
      callsCompleted: coverage.callsCompleted ?? 0,
      callsCancelled: coverage.callsCancelled ?? 0,
      providerFailures: execution.providerFailures?.length ?? 0,
      errors: result.errors?.length ?? 0,
      timeout: Boolean(coverage.timeout),
    },
    efficiency: {
      durationMs: opts.durationMs,
      inputTokens: execution.inputTokens,
      outputTokens: execution.outputTokens,
      calls: coverage.callsStarted ?? 0,
      reviewedChangedLinesPerSecond: opts.durationMs > 0 ? changedLines.reviewed / (opts.durationMs / 1000) : null,
      reviewedChangedLinesPerThousandInputTokens:
        execution.inputTokens > 0 ? changedLines.reviewed / (execution.inputTokens / 1000) : null,
    },
    honesty,
  };
}

export function collectTraceMetrics(trace: AgentSmithTrace) {
  if (!trace.execution) throw new Error(`Trace ${trace.traceId} does not contain AgentSmith execution data`);
  return collectEvalMetrics({
    scope: trace.scope,
    result: trace.result,
    execution: trace.execution,
    durationMs: trace.result.coverage.elapsedMs ?? trace.result.coverage.timeout?.elapsedMs ?? 0,
  });
}

function traceCassettes(trace: AgentSmithTrace): Cassette[] {
  const execution = trace.execution;
  if (!execution) return [];
  const rawProfiles = execution.modelProfiles as unknown;
  const profiles = Array.isArray(rawProfiles)
    ? { candidate: rawProfiles[0] as ModelProfile, verifier: (rawProfiles[1] ?? rawProfiles[0]) as ModelProfile }
    : execution.modelProfiles;
  const values: Cassette[] = [];
  for (const batch of execution.candidateBatches)
    if (batch.prompt !== undefined && batch.raw !== undefined)
      values.push({
        outputKind: "candidates",
        model: profiles.candidate.model,
        prompt: batch.prompt,
        response: {
          raw: batch.raw,
          usage: { inputTokens: batch.inputTokens, outputTokens: batch.outputTokens },
          completion: batch.completion,
        },
        used: false,
      });
  if (execution.scout)
    values.push({
      outputKind: "scout",
      model: profiles.scout?.model ?? profiles.candidate.model,
      prompt: execution.scout.prompt,
      response: {
        raw: execution.scout.raw,
        usage: { inputTokens: execution.scout.inputTokens, outputTokens: execution.scout.outputTokens },
        completion: execution.scout.completion,
      },
      used: false,
    });
  for (const verification of execution.verification)
    if (verification.prompt !== undefined && verification.raw !== undefined)
      values.push({
        outputKind: "verification",
        model: profiles.verifier.model,
        prompt: verification.prompt,
        response: {
          raw: verification.raw,
          usage: { inputTokens: 0, outputTokens: 0 },
          completion: verification.completion,
        },
        used: false,
      });
  return values;
}

export class RecordedReviewProvider implements ReviewProvider {
  private readonly cassettes: Cassette[];
  private readonly models: string[];

  constructor(trace: AgentSmithTrace) {
    this.cassettes = traceCassettes(trace);
    const rawProfiles = trace.execution?.modelProfiles as unknown;
    const profiles = Array.isArray(rawProfiles) ? rawProfiles : Object.values(trace.execution?.modelProfiles ?? {});
    this.models = [
      ...new Set(
        profiles.filter((profile): profile is ModelProfile => Boolean(profile)).map((profile) => profile.model),
      ),
    ];
  }

  async health() {
    return { ok: true, models: this.models };
  }

  async invoke(input: Parameters<ReviewProvider["invoke"]>[0]): Promise<ProviderResponse> {
    const cassette = this.cassettes.find(
      (candidate) =>
        !candidate.used &&
        candidate.outputKind === input.outputKind &&
        candidate.model === input.profile.model &&
        candidate.prompt === input.prompt,
    );
    if (!cassette)
      throw new Error(
        `Recorded replay miss for ${input.outputKind} using ${input.profile.model}; prompt or strategy changed`,
      );
    cassette.used = true;
    return structuredClone(cassette.response);
  }
}

async invoke(input: Parameters<ReviewProvider["invoke"]>[0]): Promise<ProviderResponse> {
  const cassette = this.cassettes.find(
    (candidate) =>
      !candidate.used &&
      candidate.outputKind === input.outputKind &&
      candidate.model === input.profile.model &&
      candidate.prompt === input.prompt,
  );
  if (!cassette)
    throw new Error(
      `Recorded replay miss for ${input.outputKind} using ${input.profile.model}; prompt or strategy changed`,
    );
  cassette.used = true;
  return structuredClone(cassette.response);
}

function initialCase(trace: AgentSmithTrace, slug: string): EvalCase {
  const expectedFindings = trace.result.findings.map((finding, index) => ({
    id: `expected-${index + 1}`,
    file: finding.file,
    lineStart: finding.line,
    lineEnd: finding.endLine ?? finding.line,
    severity: finding.severity,
    category: finding.category,
    discoveryClass: "L0" as const,
    requiredEvidence: finding.evidence.map((record) => record.id),
    symbols: [],
    description: finding.description,
    rationale: "REVIEW_REQUIRED",
  }));
  return {
    schemaVersion: 2,
    id: slug,
    sourceTraceId: trace.traceId,
    expectedOutcome: expectedFindings.length ? "findings" : "clear",
    expectedFindings,
    originalCandidates: (trace.execution?.candidates ?? []).map((candidate) => ({
      candidateId: candidate.id,
      label: "unreviewed",
      rationale: "",
    })),
    narrative: { summary: "", trueCodeFlow: "", references: [] },
    expectedInspectionTargets: { files: [], symbols: [], edges: [] },
    tags: [],
  };
}

export function scoreInspectionTargets(
  execution: Awaited<ReturnType<typeof executeReviewEngine>>["execution"],
  expected: EvalCase["expectedInspectionTargets"],
) {
  const inspectedFiles = new Set(execution.workItems.flatMap((item) => item.code.map((snippet) => snippet.file)));
  const inspectedSymbols = new Set(
    execution.workItems.flatMap((item) =>
      [...item.primarySymbols, ...item.relatedSymbols].flatMap((symbol) => [
        symbol.name,
        symbol.qualifiedName,
        `${symbol.file}#${symbol.qualifiedName}`,
      ]),
    ),
  );
  const inspectedEdges = new Set(
    execution.workItems.flatMap((item) =>
      item.graphEdges.flatMap((edge) => [
        `${edge.source}->${edge.target ?? edge.targetText}`,
        `${edge.source}->${edge.target ?? edge.targetText}:${edge.kind}`,
      ]),
    ),
  );
  const score = (targets: string[], inspected: Set<string>) => {
    const matched = targets.filter((target) => inspected.has(target));
    return {
      expected: targets.length,
      matched: matched.length,
      rate: targets.length ? matched.length / targets.length : null,
      missing: targets.filter((target) => !inspected.has(target)),
    };
  };
  return {
    files: score(expected.files, inspectedFiles),
    symbols: score(expected.symbols, inspectedSymbols),
    edges: score(expected.edges, inspectedEdges),
  };
}

const score = (targets: string[], inspected: Set<string>) => {
  const matched = targets.filter((target) => inspected.has(target));
  return {
    expected: targets.length,
    matched: matched.length,
    rate: targets.length ? matched.length / targets.length : null,
    missing: targets.filter((target) => !inspected.has(target)),
  };
};

function modeConfig(mode: EvalMode, config: NonNullable<ReturnType<typeof resolveConfig>["config"]["agentsmith"]>) {
  const cloned = structuredClone(config);
  cloned.cache = false;
  cloned.mode = mode === "holistic" ? "holistic" : mode === "hybrid" ? "hybrid" : "partitioned";
  return cloned;
}

export async function runEvalCases(opts: {
  root: string;
  slugs?: string[];
  modes?: EvalMode[];
  repeat?: number;
  provider?: ReviewProvider;
  replay?: EvalReplayMode;
}) {
  const slugs = opts.slugs?.length ? opts.slugs : listEvalCases(opts.root);
  if (!slugs.length) throw new Error("No AgentSmith eval cases found");
  const resolved = resolveConfig({ cwd: opts.root });
  const policy = resolvePolicyForConfig(resolved);
  const replay = opts.replay ?? "live";
  const modes = opts.modes?.length
    ? opts.modes
    : (["holistic", "partitioned-local", "partitioned-evidence", "partitioned-interactions", "hybrid"] as EvalMode[]);
  const repeat = Math.max(1, opts.repeat ?? 1);
  const cases = [];
  for (const slug of slugs) {
    const { definition, trace } = readEvalCase(opts.root, slug);
    const results = [];
    for (let iteration = 0; iteration < repeat; iteration++)
      for (const mode of modes) {
        const started = Date.now();
        try {
          const config = modeConfig(mode, resolved.config.agentsmith!);
          const provider =
            opts.provider ??
            (replay === "recorded"
              ? new RecordedReviewProvider(trace)
              : replay === "planner"
                ? new PlannerReviewProvider(config)
                : new OllamaProvider(config));
          const execution = await executeReviewEngine({
            root: opts.root,
            version: trace.version,
            scope: trace.scope,
            config,
            provider,
            profileHash: policy.agentSmith.hash,
            assetRoot: policy.agentSmith.assetRoot,
            deterministicReport: trace.deterministicReport,
            enforceWorkspaceVersion: false,
            variant: {
              includeInteractions: !["partitioned-local", "partitioned-evidence"].includes(mode),
              resolveEvidence: mode !== "partitioned-local",
            },
          });
          const promotedRejectedCandidates = definition.originalCandidates
            .filter(
              (candidate) =>
                candidate.label === "rejected" &&
                execution.result.findings.some((finding) => finding.id === candidate.candidateId),
            )
            .map((candidate) => candidate.candidateId);
          const durationMs = Date.now() - started;
          const benchmark = collectEvalMetrics({
            scope: trace.scope,
            result: execution.result,
            execution: execution.execution,
            durationMs,
          });
          const findingMetrics = scoreFindings(execution.result.findings, definition.expectedFindings);
          const inspectionTargets = scoreInspectionTargets(execution.execution, definition.expectedInspectionTargets);
          results.push({
            mode,
            outcome: execution.result.outcome,
            findings: execution.result.findings,
            coverage: execution.result.coverage,
            durationMs,
            metrics: findingMetrics,
            benchmark,
            inspectionTargets,
            qualityEvaluable: definition.expectedFindings.length > 0 || benchmark.coverage.changedFiles.rate === 1,
            outcomeCorrect: execution.result.outcome === definition.expectedOutcome,
            promotedRejectedCandidates,
            inputTokens: execution.execution.inputTokens,
            outputTokens: execution.execution.outputTokens,
            errors: execution.result.errors ?? [],
          });
        } catch (error) {
          results.push({
            mode,
            outcome: "incomplete" as const,
            findings: [],
            durationMs: Date.now() - started,
            metrics: scoreFindings([], definition.expectedFindings),
            outcomeCorrect: false,
            promotedRejectedCandidates: [],
            inputTokens: 0,
            outputTokens: 0,
            errors: [error instanceof Error ? error.message : String(error)],
          });
        }
      }
    cases.push({ id: slug, expectedOutcome: definition.expectedOutcome, results });
  }
  const runId = `${new Date().toISOString().replace(/[:.]/g, "-")}-${crypto.randomUUID()}`;
  const reportBase = { schemaVersion: 3, runId, createdAt: new Date().toISOString(), replay, modes, repeat, cases };
  const report = { ...reportBase, summary: summarizeEvalReport(reportBase) };
  const directory = path.join(opts.root, ".quality", "evals", "runs", runId);
  fs.mkdirSync(directory, { recursive: true });
  fs.writeFileSync(path.join(directory, "result.json"), `${JSON.stringify(report, null, 2)}\n`);
  const markdown = [
    `# AgentSmith eval ${runId}`,
    "",
    `Replay: ${replay}`,
    "",
    ...cases.flatMap((item) => [
      `## ${item.id}`,
      "",
      ...item.results.map(
        (result) =>
          `- ${result.mode}: outcome ${result.outcome} (expected ${item.expectedOutcome}); precision ${result.qualityEvaluable ? result.metrics.precision.toFixed(3) : "N/A"}, recall ${result.qualityEvaluable ? result.metrics.recall.toFixed(3) : "N/A"}, F1 ${result.qualityEvaluable ? result.metrics.f1.toFixed(3) : "N/A"}; file coverage ${result.benchmark ? `${((result.benchmark.coverage.changedFiles.rate ?? 0) * 100).toFixed(1)}%` : "N/A"}; line coverage ${result.benchmark ? `${((result.benchmark.coverage.changedLines.rate ?? 0) * 100).toFixed(1)}%` : "N/A"}; adjudication ${result.benchmark ? `${((result.benchmark.candidates.adjudicationRate ?? 0) * 100).toFixed(1)}%` : "N/A"}; evidence relevance ${result.benchmark?.evidence.relevanceRate === null || !result.benchmark ? "N/A" : `${(result.benchmark.evidence.relevanceRate * 100).toFixed(1)}%`}; honest ${result.benchmark?.honesty.honest ?? false}; tokens ${result.inputTokens}/${result.outputTokens}; ${result.promotedRejectedCandidates.length} rejected-candidate promotion(s); ${result.errors.length} error(s)`,
      ),
      "",
    ]),
  ].join("\n");
  fs.writeFileSync(path.join(directory, "result.md"), `${markdown}\n`);
  return { ...report, directory, markdown };
}

const benchmark = collectEvalMetrics({
  scope: trace.scope,
  result: execution.result,
  execution: execution.execution,
  durationMs,
});

function mean(values: number[]): number | null {
  return values.length ? values.reduce((sum, value) => sum + value, 0) / values.length : null;
}

function numeric(values: Array<number | null | undefined>): number[] {
  return values.filter((value): value is number => typeof value === "number" && Number.isFinite(value));
}

export function summarizeEvalReport(report: { cases: Array<{ id: string; results: any[] }> }) {
  return report.cases.flatMap((evalCase) => {
    const modes = [...new Set(evalCase.results.map((result) => result.mode as string))];
    return modes.map((mode) => {
      const results = evalCase.results.filter((result) => result.mode === mode);
      const quality = results.filter((result) => result.qualityEvaluable);
      return {
        caseId: evalCase.id,
        mode,
        runs: results.length,
        precision: mean(numeric(quality.map((result) => result.metrics?.precision))),
        recall: mean(numeric(quality.map((result) => result.metrics?.recall))),
        f1: mean(numeric(quality.map((result) => result.metrics?.f1))),
        changedFileCoverage: mean(numeric(results.map((result) => result.benchmark?.coverage.changedFiles.rate))),
        changedLineCoverage: mean(numeric(results.map((result) => result.benchmark?.coverage.changedLines.rate))),
        candidateAdjudication: mean(numeric(results.map((result) => result.benchmark?.candidates.adjudicationRate))),
        evidenceRelevance: mean(numeric(results.map((result) => result.benchmark?.evidence.relevanceRate))),
        inspectionFileRecall: mean(numeric(results.map((result) => result.inspectionTargets?.files.rate))),
        inspectionSymbolRecall: mean(numeric(results.map((result) => result.inspectionTargets?.symbols.rate))),
        inspectionEdgeRecall: mean(numeric(results.map((result) => result.inspectionTargets?.edges.rate))),
        durationMs: mean(numeric(results.map((result) => result.durationMs))),
        inputTokens: mean(numeric(results.map((result) => result.inputTokens))),
        outputTokens: mean(numeric(results.map((result) => result.outputTokens))),
        honestRunRate: mean(results.map((result) => (result.benchmark?.honesty.honest ? 1 : 0))),
        errorRuns: results.filter((result) => result.errors?.length).length,
      };
    });
  });
}

export function compareEvalReports(
  baseline: { cases: Array<{ id: string; results: any[] }> },
  current: { cases: Array<{ id: string; results: any[] }> },
) {
  const before = new Map(summarizeEvalReport(baseline).map((item) => [`${item.caseId}:${item.mode}`, item]));
  return summarizeEvalReport(current).map((item) => {
    const prior = before.get(`${item.caseId}:${item.mode}`);
    const delta = (key: keyof typeof item) => {
      const left = prior?.[key];
      const right = item[key];
      return typeof left === "number" && typeof right === "number" ? right - left : null;
    };
    return {
      caseId: item.caseId,
      mode: item.mode,
      baselineFound: Boolean(prior),
      current: item,
      delta: {
        precision: delta("precision"),
        recall: delta("recall"),
        f1: delta("f1"),
        changedFileCoverage: delta("changedFileCoverage"),
        changedLineCoverage: delta("changedLineCoverage"),
        candidateAdjudication: delta("candidateAdjudication"),
        evidenceRelevance: delta("evidenceRelevance"),
        inspectionFileRecall: delta("inspectionFileRecall"),
        inspectionSymbolRecall: delta("inspectionSymbolRecall"),
        inspectionEdgeRecall: delta("inspectionEdgeRecall"),
        durationMs: delta("durationMs"),
        inputTokens: delta("inputTokens"),
        outputTokens: delta("outputTokens"),
        honestRunRate: delta("honestRunRate"),
      },
    };
  });
}

const delta = (key: keyof typeof item) => {
  const left = prior?.[key];
  const right = item[key];
  return typeof left === "number" && typeof right === "number" ? right - left : null;
};

function compactCandidateProperties(allowedFiles?: string[]) {
  return {
    f: allowedFiles?.length ? { type: "string", enum: [...new Set(allowedFiles)] } : { type: "string", minLength: 1 },
    l: { type: "integer", minimum: 1 },
    x: { type: "integer", minimum: 1 },
    s: { type: "string", enum: ["critical", "high", "medium", "low"] },
    k: { type: "string", enum: ["correctness", "security", "performance", "contract"] },
    t: { type: "string", minLength: 1, maxLength: 80 },
    d: { type: "string", minLength: 1, maxLength: 280 },
    g: { type: "string", maxLength: 160 },
    p: { type: "string", maxLength: 160 },
    r: { type: "string", maxLength: 120 },
    q: { type: "number", minimum: 0, maximum: 1 },
    e: {
      type: "array",
      maxItems: 2,
      items: {
        type: "object",
        additionalProperties: false,
        required: ["k", "r"],
        properties: {
          k: {
            type: "string",
            enum: [
              "definition",
              "callers",
              "callees",
              "type",
              "implementation",
              "usage",
              "config",
              "test",
              "schema",
              "search",
            ],
          },
          s: { type: "string", maxLength: 160 },
          p: { type: "string", maxLength: 240 },
          q: { type: "string", maxLength: 240 },
          r: { type: "string", minLength: 1, maxLength: 120 },
        },
      },
    },
  };
}

function outputSchema(kind: ReviewOutputKind, allowedFiles?: string[], maxCandidates = 2) {
  if (kind === "verification")
    return {
      type: "object",
      additionalProperties: false,
      required: ["verdict", "confidence", "supportingEvidenceIds"],
      properties: {
        verdict: { type: "string", enum: ["verified", "likely", "rejected", "insufficient_evidence"] },
        confidence: { type: "number", minimum: 0, maximum: 1 },
        reasoningSummary: { type: "string" },
        supportingEvidenceIds: { type: "array", items: { type: "string" } },
      },
    };
  if (kind === "scout")
    return {
      type: "object",
      additionalProperties: false,
      required: ["hotspots"],
      properties: {
        hotspots: {
          type: "array",
          items: {
            type: "object",
            additionalProperties: false,
            required: ["hotspotId", "risk", "category", "symbols", "edges", "rationale", "requestedInspection"],
            properties: {
              hotspotId: { type: "string" },
              risk: { type: "string", enum: ["critical", "high", "medium", "low"] },
              category: { type: "string", enum: ["correctness", "security", "performance", "contract"] },
              symbols: { type: "array", items: { type: "string" } },
              edges: { type: "array", items: { type: "string" } },
              rationale: { type: "string" },
              requestedInspection: {
                type: "object",
                required: ["symbols"],
                properties: {
                  symbols: { type: "array", items: { type: "string" } },
                  edgeKinds: { type: "array", items: { type: "string" } },
                },
              },
            },
          },
        },
      },
    };
  return {
    type: "object",
    additionalProperties: false,
    required: ["c"],
    properties: {
      c: {
        type: "array",
        maxItems: maxCandidates,
        items: {
          type: "object",
          additionalProperties: false,
          required: ["f", "l", "s", "k", "t", "d", "q", "e"],
          properties: compactCandidateProperties(allowedFiles),
        },
      },
    },
  };
}

function extractStructured(raw: string): string {
  if (raw.length > 256_000) throw new Error("AgentSmith response exceeds 256000 characters");
  const fenced = /```(?:json)?\s*\n?([\s\S]*?)```/i.exec(raw);
  if (fenced) return fenced[1].trim();
  const start = raw.indexOf("{");
  const end = raw.lastIndexOf("}");
  if (start >= 0 && end > start) return raw.slice(start, end + 1);
  return raw.trim();
}

export function parseVerdict(raw: string): ParsedVerdict {
  let data: any;
  try {
    const structured = extractStructured(raw);
    data = JSON.parse(structured);
    if (!data || typeof data !== "object" || Array.isArray(data)) throw new Error("not a mapping");
  } catch {
    throw new Error("AgentSmith parse-verdict: no valid JSON object found in provider output");
  }
  const schema = z.object({
    verdict: z.string().optional(),
    summary: z.string().optional(),
    findings: z
      .array(
        z.object({
          severity: z.unknown().optional(),
          message: z.unknown().optional(),
          file: z.string().optional(),
          line: z.number().int().positive().optional(),
          col: z.number().int().positive().optional(),
          ruleId: z.string().optional(),
          domain: z.string().optional(),
          evidence: z.string().optional(),
          impact: z.string().optional(),
          recommendation: z.string().optional(),
        }),
      )
      .default([]),
  });
  const validated = schema.safeParse(data);
  if (!validated.success) throw new Error(`AgentSmith verdict schema invalid: ${validated.error.message}`);
  data = validated.data;
  const verdictRaw = String(data?.verdict ?? "").toUpperCase();
  const verdict: Verdict = VERDICTS.includes(verdictRaw as Verdict) ? (verdictRaw as Verdict) : "REQUEST_CHANGES";
  const findings: LegacyReviewFinding[] = Array.isArray(data?.findings)
    ? data.findings.map((finding: any, index: number) => ({
        severity: normalizeSeverity(finding?.severity),
        message: String(finding?.message ?? `finding ${index + 1}`),
        file: typeof finding?.file === "string" ? finding.file : undefined,
        line: typeof finding?.line === "number" ? finding.line : undefined,
        col: typeof finding?.col === "number" ? finding.col : undefined,
        ruleId: typeof finding?.ruleId === "string" ? finding.ruleId : undefined,
        domain: DOMAINS.includes(finding?.domain as LegacyReviewFindingDomain)
          ? (finding.domain as LegacyReviewFindingDomain)
          : undefined,
        evidence: typeof finding?.evidence === "string" ? finding.evidence : undefined,
        impact: typeof finding?.impact === "string" ? finding.impact : undefined,
        recommendation: typeof finding?.recommendation === "string" ? finding.recommendation : undefined,
      }))
    : [];
  return {
    verdict: verdict === "APPROVE" && findings.length > 0 ? "RISK" : verdict,
    summary: typeof data?.summary === "string" ? data.summary : "",
    findings,
  };
}

function traceTokens(value: string | undefined): string[] {
  return (value ?? "")
    .split(/[\s,]+/)
    .map((token) => token.trim().toLowerCase())
    .filter(Boolean);
}

export function isAgentSmithTraceEnabled(env: NodeJS.ProcessEnv = process.env): boolean {
  const tokens = traceTokens(env[TRACE_ENV]);
  return !tokens.some((token) => ["0", "false", "none", "off"].includes(token));
}

export function tracesRoot(root: string): string {
  return path.join(root, ".quality", "traces", "agentsmith");
}

function directorySize(target: string): number {
  try {
    return fs.readdirSync(target, { withFileTypes: true }).reduce((total, entry) => {
      const child = path.join(target, entry.name);
      return total + (entry.isDirectory() ? directorySize(child) : fs.statSync(child).size);
    }, 0);
  } catch {
    return 0;
  }
}

export function pruneAgentSmithTraces(
  root: string,
  limits: { maxCount?: number; maxBytes?: number } = {},
): { removed: string[]; retained: number; bytes: number } {
  const maxCount = Math.max(1, limits.maxCount ?? TRACE_MAX_COUNT);
  const maxBytes = Math.max(1, limits.maxBytes ?? TRACE_MAX_BYTES);
  const directory = tracesRoot(root);
  let entries: Array<{ id: string; path: string; modifiedMs: number; bytes: number }> = [];
  try {
    entries = fs
      .readdirSync(directory, { withFileTypes: true })
      .filter((entry) => entry.isDirectory())
      .map((entry) => {
        const target = path.join(directory, entry.name);
        return { id: entry.name, path: target, modifiedMs: fs.statSync(target).mtimeMs, bytes: directorySize(target) };
      })
      .sort((left, right) => right.modifiedMs - left.modifiedMs || right.id.localeCompare(left.id));
  } catch {
    return { removed: [], retained: 0, bytes: 0 };
  }
  const removed: string[] = [];
  let retained = 0;
  let bytes = 0;
  for (const entry of entries) {
    // Keep the newest trace even when a single unusually large trace exceeds the byte budget.
    if (retained === 0 || (retained < maxCount && bytes + entry.bytes <= maxBytes)) {
      retained += 1;
      bytes += entry.bytes;
      continue;
    }
    try {
      fs.rmSync(entry.path, { recursive: true, force: true });
      removed.push(entry.id);
    } catch {
      // Retention failure must not change the review decision.
    }
  }
  return { removed, retained, bytes };
}

export function writeAgentSmithTrace(
  root: string,
  input: Omit<AgentSmithTrace, "schemaVersion" | "traceId" | "captureMode" | "createdAt" | "root">,
): { traceId?: string; warning?: string } {
  if (!isAgentSmithTraceEnabled()) return {};
  const traceId = createTraceId();
  const directory = path.join(tracesRoot(root), traceId);
  const target = path.join(directory, "trace.json");
  const temporary = `${target}.${process.pid}.tmp`;
  try {
    fs.mkdirSync(directory, { recursive: true });
    const trace: AgentSmithTrace = {
      ...input,
      schemaVersion: 2,
      traceId,
      captureMode: traceTokens(process.env[TRACE_ENV]).some((token) => ["agentsmith", "all"].includes(token))
        ? "explicit-local"
        : "automatic-local",
      createdAt: new Date().toISOString(),
      root,
    };
    fs.writeFileSync(temporary, `${JSON.stringify(trace, null, 2)}\n`, { encoding: "utf8", mode: 0o600 });
    fs.renameSync(temporary, target);
    pruneAgentSmithTraces(root);
    return { traceId };
  } catch (error) {
    try {
      fs.unlinkSync(temporary);
    } catch {
      /* best effort */
    }
    return { warning: `AgentSmith trace was not written: ${error instanceof Error ? error.message : String(error)}` };
  }
}

const trace: AgentSmithTrace = {
  ...input,
  schemaVersion: 2,
  traceId,
  captureMode: traceTokens(process.env[TRACE_ENV]).some((token) => ["agentsmith", "all"].includes(token))
    ? "explicit-local"
    : "automatic-local",
  createdAt: new Date().toISOString(),
  root,
};

export function traceStatus(root: string) {
  const check = spawnSync("git", ["check-ignore", "-q", ".quality/"], { cwd: root });
  return {
    enabled: isAgentSmithTraceEnabled(),
    activation: `automatic; set ${TRACE_ENV}=off to disable`,
    directory: tracesRoot(root),
    gitIgnored: check.status === 0,
    uploadCapability: false,
    traceCount: listAgentSmithTraces(root).length,
    retention: { maxCount: TRACE_MAX_COUNT, maxBytes: TRACE_MAX_BYTES },
  };
}

function identity(root: string): CompletionIdentity {
  const resolved = resolveConfig({ cwd: root });
  return {
    repositoryHash: computeWorkspaceVersion(root),
    policyHash: resolvePolicyForConfig(resolved).policyHash,
  };
}

function sameIdentity(left: CompletionIdentity, right: CompletionIdentity): boolean {
  return left.repositoryHash === right.repositoryHash && left.policyHash === right.policyHash;
}

function readJson<T>(file: string): T | null {
  try {
    return JSON.parse(fs.readFileSync(file, "utf8")) as T;
  } catch {
    return null;
  }
}

function atomicWrite(file: string, value: unknown): void {
  fs.mkdirSync(path.dirname(file), { recursive: true });
  const temporary = `${file}.${process.pid}.${crypto.randomUUID()}.tmp`;
  fs.writeFileSync(temporary, `${JSON.stringify(value, null, 2)}\n`);
  fs.renameSync(temporary, file);
}

function processAlive(pid: number): boolean {
  try {
    process.kill(pid, 0);
    return true;
  } catch (error) {
    return (error as NodeJS.ErrnoException).code === "EPERM";
  }
}

function appendEvent(root: string, event: Record<string, unknown>): void {
  try {
    const file = qualityStorePath(root, "completion-events.jsonl");
    fs.mkdirSync(path.dirname(file), { recursive: true });
    fs.appendFileSync(file, `${JSON.stringify({ timestamp: new Date().toISOString(), ...event })}\n`);
  } catch {}
}

function wait(delayMs: number, signal?: AbortSignal): Promise<void> {
  return new Promise((resolve, reject) => {
    if (signal?.aborted) return reject(signal.reason ?? new Error("Completion cancelled"));
    const onAbort = () => {
      clearTimeout(timer);
      reject(signal?.reason ?? new Error("Completion cancelled"));
    };
    const timer = setTimeout(() => {
      signal?.removeEventListener("abort", onAbort);
      resolve();
    }, delayMs);
    signal?.addEventListener("abort", onAbort, { once: true });
  });
}

async function coordinatedRun(
  root: string,
  signal: AbortSignal | undefined,
  execute: () => Promise<QualityCompletionResult>,
): Promise<QualityCompletionResult> {
  const requestedIdentity = identity(root);
  const lockPath = qualityStorePath(root, COMPLETION_LOCK_FILE);
  const resultPath = qualityStorePath(root, COMPLETION_RESULT_FILE);
  fs.mkdirSync(path.dirname(lockPath), { recursive: true });

  while (true) {
    if (signal?.aborted) throw signal.reason ?? new Error("Completion cancelled");
    let descriptor: number;
    try {
      descriptor = fs.openSync(lockPath, "wx");
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code !== "EEXIST") throw error;
      const active = readJson<CompletionLock>(lockPath);
      const expired = active ? Date.parse(active.leaseUntil) <= Date.now() : false;
      const dead = active ? active.hostname === os.hostname() && !processAlive(active.pid) : false;
      let malformedAndStale = false;
      if (!active) {
        try {
          malformedAndStale = Date.now() - fs.statSync(lockPath).mtimeMs > 60_000;
        } catch {}
      }
      if ((active && (expired || dead)) || malformedAndStale) {
        const latest = readJson<CompletionLock>(lockPath);
        if ((active && latest?.runId === active.runId) || (!active && latest === null)) {
          fs.unlinkSync(lockPath);
          appendEvent(root, {
            type: "stale_lock_recovered",
            runId: active?.runId ?? null,
            pid: active?.pid ?? null,
          });
          continue;
        }
      }
      const joinedRunId = active?.runId;
      appendEvent(root, { type: "run_joined", runId: joinedRunId ?? null, pid: process.pid });
      while (fs.existsSync(lockPath)) await wait(100, signal);
      const completed = readJson<StoredCompletionResult>(resultPath);
      if (completed && completed.runId === joinedRunId && sameIdentity(completed.identity, requestedIdentity)) {
        if (completed.status === "COMPLETED" && completed.result) return completed.result;
        throw new Error(completed.error ?? "Joined completion run failed");
      }
      continue;
    }

    const runId = crypto.randomUUID();
    const acquiredIdentity = identity(root);
    const resolved = resolveConfig({ cwd: root });
    const duration = Math.max(60_000, resolved.config.agentsmith?.maxDurationMs ?? 600_000) + 60_000;
    const startedAt = new Date().toISOString();
    let lock: CompletionLock = {
      schemaVersion: 1,
      runId,
      pid: process.pid,
      hostname: os.hostname(),
      startedAt,
      updatedAt: startedAt,
      leaseUntil: new Date(Date.now() + duration).toISOString(),
      identity: acquiredIdentity,
    };
    const writeLock = () => {
      lock = {
        ...lock,
        updatedAt: new Date().toISOString(),
        leaseUntil: new Date(Date.now() + duration).toISOString(),
      };
      fs.ftruncateSync(descriptor, 0);
      fs.writeSync(descriptor, `${JSON.stringify(lock, null, 2)}\n`, 0, "utf8");
      fs.fsyncSync(descriptor);
    };
    writeLock();
    const heartbeat = setInterval(writeLock, 5000);
    heartbeat.unref();
    appendEvent(root, { type: "run_started", runId, pid: process.pid, ...acquiredIdentity });
    try {
      const result = await execute();
      const stored: StoredCompletionResult = {
        schemaVersion: 1,
        runId,
        identity: acquiredIdentity,
        status: "COMPLETED",
        completedAt: new Date().toISOString(),
        result,
      };
      atomicWrite(resultPath, stored);
      appendEvent(root, {
        type: "run_completed",
        runId,
        result: result.completionAllowed ? "PASS" : result.gate.status === "FAIL" ? "REJECT" : "ERROR",
      });
      return result;
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      atomicWrite(resultPath, {
        schemaVersion: 1,
        runId,
        identity: acquiredIdentity,
        status: "ERROR",
        completedAt: new Date().toISOString(),
        error: message,
      } satisfies StoredCompletionResult);
      appendEvent(root, { type: "run_error", runId, error: message });
      throw error;
    } finally {
      clearInterval(heartbeat);
      fs.closeSync(descriptor);
      const current = readJson<CompletionLock>(lockPath);
      if (current?.runId === runId) fs.unlinkSync(lockPath);
    }
  }
}

const writeLock = () => {
  lock = {
    ...lock,
    updatedAt: new Date().toISOString(),
    leaseUntil: new Date(Date.now() + duration).toISOString(),
  };
  fs.ftruncateSync(descriptor, 0);
  fs.writeSync(descriptor, `${JSON.stringify(lock, null, 2)}\n`, 0, "utf8");
  fs.fsyncSync(descriptor);
};

const stored: StoredCompletionResult = {
  schemaVersion: 1,
  runId,
  identity: acquiredIdentity,
  status: "COMPLETED",
  completedAt: new Date().toISOString(),
  result,
};

export function coordinateQualityCompletion(
  root: string,
  signal: AbortSignal | undefined,
  execute: () => Promise<QualityCompletionResult>,
): Promise<QualityCompletionResult> {
  const canonicalRoot = fs.realpathSync(root);
  const existing = localRuns.get(canonicalRoot);
  if (existing) return existing;
  const running = coordinatedRun(canonicalRoot, signal, execute).finally(() => {
    if (localRuns.get(canonicalRoot) === running) localRuns.delete(canonicalRoot);
  });
  localRuns.set(canonicalRoot, running);
  return running;
}

