export async function runQualityReview(
  opts: RunGateOptions & { configFlag?: string; signal?: AbortSignal; provider?: ReviewProvider },
): Promise<QualityReviewResult> {
  const resolved = resolveConfig({ configFlag: opts.configFlag, cwd: opts.cwd });
  const scope = captureReviewScope({
    root: resolved.configRoot,
    base: opts.base,
    contextFiles: resolved.config.agentsmith?.context_files,
  });
  const gate = await runGate(opts);
  const review: ReviewResult =
    gate.status !== "PASS"
      ? unavailableReview(gate.version, "AgentSmith was not run because the deterministic gate failed")
      : resolved.config.agentsmith?.enabled === false
        ? unavailableReview(gate.version, "AgentSmith disabled")
        : await runReview({
            cwd: resolved.configRoot,
            version: gate.version,
            base: opts.base,
            report: JSON.stringify({
              status: gate.status,
              checks: gate.checks,
              failures: gate.failures,
              metrics: gate.metrics,
            }),
            config: opts.configFlag,
            signal: opts.signal,
            scope,
            provider: opts.provider,
          });
  writeResult(resolved.configRoot, review, gate.status);
  const advisory = resolved.config.agentsmith?.advisory !== false;
  const reviewArtifact = REVIEW_MARKDOWN_ARTIFACT;
  return {
    version: gate.version,
    gate,
    review,
    advisory,
    reviewMarkdown: formatAgentSmithReview(review, { gateStatus: gate.status, artifact: reviewArtifact }),
    reviewArtifact,
    passed:
      gate.status === "PASS" &&
      computeWorkspaceVersion(resolved.configRoot) === scope.version &&
      (advisory || (review.status === "completed" && review.outcome === "clear")),
  };
}

async function runQualityCompletionOnce(
  opts: RunGateOptions & { configFlag?: string; signal?: AbortSignal; provider?: ReviewProvider },
): Promise<QualityCompletionResult> {
  const resolved = resolveConfig({ configFlag: opts.configFlag, cwd: opts.cwd });
  const host = opts.adapter === "mcp" ? "mcp" : "cli";
  if (resolved.config.agentsmith?.enabled) {
    const result = await runQualityReview(opts);
    const current = getQualityStatus(resolved.configRoot);
    const status =
      result.gate.status !== "PASS"
        ? "disabled"
        : result.review.coverage.timeout
          ? "timeout"
          : result.review.errors?.length
            ? "provider_error"
            : result.review.status === "partial"
              ? "partial"
              : "completed";
    turnStore.recordGateResult(
      resolved.configRoot,
      result.gate,
      current.completionAllowed ? "PASS" : result.gate.status === "FAIL" ? "REJECT" : "ERROR",
      host,
    );
    return {
      ...result,
      reviewEnabled: true,
      deterministicPassed: result.gate.status === "PASS",
      completionAllowed: current.completionAllowed,
      passed: current.completionAllowed,
      advisoryReview: {
        status,
        verdict: result.review.findings.length > 0 ? "findings" : result.review.outcome === "clear" ? "pass" : null,
        findings: result.review.findings,
        errors: result.review.errors ?? [],
        profileId: result.gate.policy?.agentSmith.id ?? null,
        profileHash: result.gate.policy?.agentSmith.hash ?? null,
        completedAt: result.review.timestamp,
      },
    };
  }
  const gate = await runGate(opts);
  const current = getQualityStatus(resolved.configRoot);
  turnStore.recordGateResult(resolved.configRoot, gate, current.completionAllowed ? "PASS" : "REJECT", host);
  return {
    version: gate.version,
    gate,
    review: null,
    reviewEnabled: false,
    advisory: true,
    passed: current.completionAllowed,
    deterministicPassed: gate.status === "PASS",
    completionAllowed: current.completionAllowed,
    reviewMarkdown: formatAgentSmithReview(null, { gateStatus: gate.status }),
    reviewArtifact: null,
    advisoryReview: {
      status: "disabled",
      verdict: null,
      findings: [],
      errors: [],
      profileId: null,
      profileHash: null,
    },
  };
}

export async function runQualityCompletion(
  opts: RunGateOptions & { configFlag?: string; signal?: AbortSignal; provider?: ReviewProvider },
): Promise<QualityCompletionResult> {
  const resolved = resolveConfig({ configFlag: opts.configFlag, cwd: opts.cwd });
  return coordinateQualityCompletion(resolved.configRoot, opts.signal, () => runQualityCompletionOnce(opts));
}

export function versionAccepted(version: string, range: string) {
  return version === range;
}

const capMap = new Map([
  [
    check.tool === "tsc" ? "typescript" : check.tool,
    { name: check.tool, found: true, version, path: binary, required: true },
  ],
]);

export function canonicalPath(value: string): string {
  const absolute = path.resolve(value);
  return fs.realpathSync(absolute);
}

export function recordEngineRuntime(root: string, adapter: "mcp" | "hook" | "cli"): EngineRuntimeIdentity {
  const canonicalRoot = canonicalPath(root);
  const runtime = engineRuntimeIdentity();
  const directory = path.join(canonicalRoot, GATE_STORE_DIR);
  const target = path.join(directory, `${adapter}-runtime.json`);
  const temporary = `${target}.${process.pid}.${crypto.randomUUID()}.tmp`;
  fs.mkdirSync(directory, { recursive: true });
  fs.writeFileSync(
    temporary,
    `${JSON.stringify({ schemaVersion: 2, adapter, recordedAt: new Date().toISOString(), pid: process.pid, parentPid: process.ppid, ...runtime }, null, 2)}\n`,
  );
  fs.renameSync(temporary, target);
  if (adapter === "mcp") recordMcpProcessRuntime(canonicalRoot, runtime);
  return runtime;
}

export function cleanupMcpRuntimeRecords(): void {
  for (const target of mcpRuntimeFiles) {
    try {
      fs.unlinkSync(target);
    } catch {}
  }
  mcpRuntimeFiles.clear();
}

function pidAlive(pid: number): boolean {
  try {
    process.kill(pid, 0);
    return true;
  } catch (error) {
    return (error as NodeJS.ErrnoException).code === "EPERM";
  }
}

export function getQualityStatus(cwd: string): QualityStatus {
  const resolved = resolveConfig({ cwd });
  const runtime = engineRuntimeIdentity();
  if (resolved.isDefault) {
    return {
      schemaVersion: 1,
      configured: false,
      root: resolved.configRoot,
      version: null,
      gate: null,
      review: null,
      ...reviewPresentation(null),
      completionAllowed: true,
      runtime,
      reason: "MatrixCore is not configured for this workspace",
    };
  }

  const root = resolved.configRoot;
  let policy: ResolvedPolicy;
  try {
    policy = resolvePolicyForConfig(resolved);
  } catch (error) {
    const version = computeWorkspaceVersion(root);
    const review = readReviewResult(root);
    return {
      schemaVersion: 1,
      configured: true,
      root,
      version,
      gate: readGateResult(root, "full"),
      changedGate: readGateResult(root, "changed"),
      review,
      ...reviewPresentation(review),
      reviewRequired: resolved.config.review?.agentsmith ?? false,
      completionAllowed: false,
      reason: `MatrixCore policy unavailable: ${error instanceof Error ? error.message : String(error)}`,
      runtime,
    };
  }
  const workspaceSet = resolveWorkspaceSet(root, resolved.config.application);
  const workspaces = workspaceSet.workspaces;
  const version = computeWorkspaceVersion(root);
  const gate = readGateResult(root, "full");
  const changedGate = readGateResult(root, "changed");
  const review = readReviewResult(root);
  const reviewRequired = resolved.config.agentsmith?.enabled === true;
  const reviewAdvisory = resolved.config.agentsmith?.advisory !== false;
  const reviewBlocksCompletion = reviewRequired && !reviewAdvisory;
  const currentIdentity: CompletionIdentitySnapshot = {
    workspaceVersion: version,
    workspaceHash: workspaceSet.workspaceHash,
    policyHash: policy.policyHash,
    toolVersions: currentToolVersions(workspaces, policy),
    engineVersion: runtime.version,
    enginePath: runtime.executablePath,
    enginePackageRoot: runtime.packageRoot,
  };
  const identity = compareCompletionIdentity(gate, currentIdentity);
  if (!gate)
    return {
      schemaVersion: 1,
      configured: true,
      root,
      version,
      gate: null,
      changedGate,
      review,
      ...reviewPresentation(review),
      reviewRequired,
      reviewEnabled: reviewRequired,
      reviewAdvisory,
      completionAllowed: false,
      reason: readLegacyGateResult(root)
        ? "Legacy gate evidence has no execution scope and cannot authorize completion. Run quality_run with mode=completion."
        : "Quality gate has not been run. Run quality_run with mode=completion before finishing.",
      workspaces,
      workspaceHash: workspaceSet.workspaceHash,
      policy,
      runtime,
      identity,
    };
  if (gate.status !== "PASS")
    return {
      schemaVersion: 1,
      configured: true,
      root,
      version,
      gate,
      changedGate,
      review,
      ...reviewPresentation(review, gate.status),
      reviewRequired,
      completionAllowed: false,
      reason: `Quality gate is ${gate.status}. Fix deterministic failures and run quality_run with mode=completion.`,
      workspaces,
      workspaceHash: workspaceSet.workspaceHash,
      policy,
      runtime,
      identity,
    };
  if (gate.schemaVersion !== 2 || gate.mode !== "full" || gate.fast)
    return {
      schemaVersion: 1,
      configured: true,
      root,
      version,
      gate,
      changedGate,
      review,
      ...reviewPresentation(review, gate.status),
      reviewRequired,
      completionAllowed: false,
      reason: "Completion requires a full, non-fast deterministic gate. Run quality_run with mode=completion.",
      workspaces,
      workspaceHash: workspaceSet.workspaceHash,
      policy,
      runtime,
      identity,
    };
  if (
    !gateMatchesIdentity(gate, { version, workspaceHash: workspaceSet.workspaceHash, policyHash: policy.policyHash }) ||
    identity.mismatches.length > 0
  )
    return {
      schemaVersion: 1,
      configured: true,
      root,
      version,
      gate,
      changedGate,
      review,
      ...reviewPresentation(review, gate.status),
      reviewRequired,
      completionAllowed: false,
      reason: mismatchReason(identity),
      workspaces,
      workspaceHash: workspaceSet.workspaceHash,
      policy,
      runtime,
      identity,
    };
  if (
    reviewBlocksCompletion &&
    (!review ||
      review.version !== version ||
      review.profileHash !== policy.agentSmith.hash ||
      review.status === "stale")
  )
    return {
      schemaVersion: 1,
      configured: true,
      root,
      version,
      gate,
      changedGate,
      review,
      ...reviewPresentation(review, gate.status),
      reviewRequired,
      reviewEnabled: reviewRequired,
      reviewAdvisory,
      completionAllowed: false,
      reason: "AgentSmith review is missing or stale. Run quality_run with mode=completion before finishing.",
      workspaces,
      workspaceHash: workspaceSet.workspaceHash,
      policy,
      runtime,
      identity,
    };
  if (reviewBlocksCompletion && (!review || review.status !== "completed" || Boolean(review.errors?.length)))
    return {
      schemaVersion: 1,
      configured: true,
      root,
      version,
      gate,
      changedGate,
      review,
      ...reviewPresentation(review, gate.status),
      reviewRequired,
      reviewEnabled: reviewRequired,
      reviewAdvisory,
      completionAllowed: false,
      reason:
        "AgentSmith review did not complete successfully. Resolve provider/review errors and run quality_run with mode=completion.",
      workspaces,
      workspaceHash: workspaceSet.workspaceHash,
      policy,
      runtime,
      identity,
    };
  return {
    schemaVersion: 1,
    configured: true,
    root,
    version,
    gate,
    changedGate,
    review,
    ...reviewPresentation(review, gate.status),
    reviewRequired,
    reviewEnabled: reviewRequired,
    reviewAdvisory,
    completionAllowed: true,
    workspaces,
    workspaceHash: workspaceSet.workspaceHash,
    policy,
    runtime,
    identity,
  };
}

function toValidationEvidence(gate: GateResult, policyHash: string): ValidationEvidence {
  const checks = gate.checks.map((c) => ({
    name: c.plugin,
    status: c.status as "PASS" | "FAIL" | "ERROR" | "SKIPPED",
    findings: c.observations?.map((o) => o.message) ?? [],
  }));
  return {
    schemaVersion: 1,
    repositoryHash: gate.version,
    policyHash,
    result: gate.status === "PASS" ? "PASS" : gate.status === "FAIL" ? "REJECT" : "ERROR",
    checks,
    timestamp: new Date().toISOString(),
    gateVersion: gate.version,
    gateMode: gate.mode,
    gateFast: gate.fast,
  };
}

function getPolicyHash(root: string): string {
  const resolved = resolveConfig({ cwd: root });
  const policy = resolvePolicyForConfig(resolved);
  return policy.policyHash;
}

onDirty(host: "cline" | "codex" | "claude" = "cline", turnId?: string): void {
  const currentHash = computeWorkspaceVersion(this.root);
  turnStore.setDirty(this.root, currentHash, host, turnId);
}

getStatus(): TurnGateState {
  return turnStore.getState(this.root);
}

function storePath(root: string): string {
  return path.join(root, STORE_DIR, STATE_FILE);
}

function eventsPath(root: string): string {
  return path.join(root, STORE_DIR, EVENTS_FILE);
}

function currentPolicyHash(root: string): string | null {
  try {
    return resolvePolicyForConfig(resolveConfig({ cwd: root })).policyHash;
  } catch {
    return null;
  }
}

function withStoreLock<T>(root: string, action: () => T): T {
  const lockPath = path.join(root, STORE_DIR, "turn-state.lock");
  fs.mkdirSync(path.dirname(lockPath), { recursive: true });
  let fd: number | undefined;
  for (let attempt = 0; attempt < 200; attempt += 1) {
    try {
      fd = fs.openSync(lockPath, "wx");
      break;
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code !== "EEXIST") throw error;
      const wait = new Int32Array(new SharedArrayBuffer(4));
      Atomics.wait(wait, 0, 0, 10);
    }
  }
  if (fd === undefined) throw new Error("Timed out acquiring MatrixCore turn-state lock");
  try {
    return action();
  } finally {
    fs.closeSync(fd);
    try {
      fs.unlinkSync(lockPath);
    } catch {}
  }
}

function defaultState(): TurnGateState {
  return {
    schemaVersion: 1,
    dirty: false,
    currentHash: null,
    validatedHash: null,
    status: "RUNNING",
    attempts: 0,
    lastValidationEvidence: null,
    retryCountByHash: {},
    activeTurnId: null,
    updatedAt: new Date().toISOString(),
  };
}

function readState(root: string): TurnGateState {
  const p = storePath(root);
  try {
    const raw = fs.readFileSync(p, "utf8");
    const parsed = JSON.parse(raw) as TurnGateState;
    if (parsed.schemaVersion === 1) return parsed;
  } catch {}
  return defaultState();
}

function writeState(root: string, state: TurnGateState): void {
  const dir = path.dirname(storePath(root));
  fs.mkdirSync(dir, { recursive: true });
  const tmp = `${storePath(root)}.${process.pid}.${crypto.randomUUID()}.tmp`;
  state.updatedAt = new Date().toISOString();
  fs.writeFileSync(tmp, JSON.stringify(state, null, 2));
  fs.renameSync(tmp, storePath(root));
}

getState(root: string): TurnGateState {
  return readState(root);
},

setDirty(
  root: string,
  currentHash: string,
  host: "cline" | "codex" | "claude" | "cli" | "mcp" = "cline",
  turnId?: string,
): void {
  withStoreLock(root, () => {
    const state = readState(root);
    state.dirty = true;
    state.currentHash = currentHash;
    state.status = "RUNNING";
    if (turnId) state.activeTurnId = turnId;
    writeState(root, state);
    appendEvent(root, {
      type: "DIRTY",
      host,
      turnId,
      payload: { hash: currentHash },
      timestamp: new Date().toISOString(),
    });
  });
},

candidateComplete(
  root: string,
  host: "cline" | "codex" | "claude",
  currentHash: string,
  turnId?: string,
): TurnGateState {
  return withStoreLock(root, () => {
    const state = readState(root);
    if (turnId && state.activeTurnId !== turnId) {
      state.retryCountByHash = {};
      state.activeTurnId = turnId;
    }
    state.currentHash = currentHash;
    state.attempts += 1;
    state.status = "VALIDATING";
    const count = state.retryCountByHash[currentHash] || 0;
    state.retryCountByHash[currentHash] = count + 1;
    writeState(root, state);
    appendEvent(root, {
      type: "CANDIDATE_COMPLETE",
      host,
      turnId,
      payload: { hash: currentHash },
      timestamp: new Date().toISOString(),
    });
    return state;
  });
},

validationComplete(
  root: string,
  evidence: ValidationEvidence,
  host: "cline" | "codex" | "claude" | "cli" | "mcp" = "cline",
  turnId?: string,
): TurnGateState {
  return withStoreLock(root, () => {
    const state = readState(root);
    const liveHash = computeWorkspaceVersion(root);
    const policyMatches = currentPolicyHash(root) === evidence.policyHash;
    state.currentHash = liveHash;
    const completionEligible = evidence.gateMode === "full" && evidence.gateFast !== true;
    state.dirty =
      evidence.result !== "PASS" || !completionEligible || liveHash !== evidence.repositoryHash || !policyMatches;
    if (evidence.result === "PASS" && completionEligible && liveHash === evidence.repositoryHash && policyMatches) {
      state.validatedHash = evidence.repositoryHash;
      state.status = "VALIDATED_COMPLETE";
    } else {
      state.status = evidence.result === "REJECT" ? "REJECT" : "ERROR";
    }
    state.lastValidationEvidence = evidence;
    if (turnId) state.activeTurnId = turnId;
    if (
      evidence.result === "PASS" &&
      completionEligible &&
      liveHash === evidence.repositoryHash &&
      policyMatches &&
      state.retryCountByHash[evidence.repositoryHash]
    ) {
      delete state.retryCountByHash[evidence.repositoryHash];
    }
    writeState(root, state);
    appendEvent(root, {
      type:
        liveHash === evidence.repositoryHash && evidence.result === "PASS" && completionEligible && policyMatches
          ? "VALIDATED_COMPLETE"
          : "VALIDATION_COMPLETE",
      host,
      turnId,
      payload: { result: evidence.result, hash: evidence.repositoryHash, liveHash, policyMatches },
      timestamp: new Date().toISOString(),
    });
    return state;
  });
},

validationFailed(
  root: string,
  currentHash: string,
  host: "cline" | "codex" | "claude" = "cline",
  turnId?: string,
): TurnGateState {
  return withStoreLock(root, () => {
    const state = readState(root);
    state.status = "VALIDATION_FAILED";
    state.dirty = true;
    state.currentHash = currentHash;
    writeState(root, state);
    appendEvent(root, {
      type: "GATE_FAILED",
      host,
      turnId,
      payload: { result: "ERROR", hash: currentHash },
      timestamp: new Date().toISOString(),
    });
    return state;
  });
},

cancelled(root: string): TurnGateState {
  return withStoreLock(root, () => {
    const state = readState(root);
    state.status = "CANCELLED";
    writeState(root, state);
    appendEvent(root, {
      type: "CANCELLED",
      host: "cline",
      payload: { result: "CANCELLED" },
      timestamp: new Date().toISOString(),
    });
    return state;
  });
},

failed(root: string, error: string, host: "cline" | "codex" | "claude" = "cline", turnId?: string): TurnGateState {
  return withStoreLock(root, () => {
    const state = readState(root);
    state.status = "ERROR";
    state.dirty = true;
    state.currentHash = state.currentHash || computeWorkspaceVersion(root);
    writeState(root, state);
    appendEvent(root, {
      type: "GATE_FAILED",
      host,
      turnId,
      payload: { result: "ERROR", error },
      timestamp: new Date().toISOString(),
    });
    return state;
  });
},

reset(root: string): TurnGateState {
  return withStoreLock(root, () => {
    const state = defaultState();
    writeState(root, state);
    appendEvent(root, { type: "RESET", host: "cline", payload: {}, timestamp: new Date().toISOString() });
    return state;
  });
},

listEvents(root: string, limit = 50): TurnEvent[] {
  const p = eventsPath(root);
  try {
    const lines = fs.readFileSync(p, "utf8").trim().split("\n").filter(Boolean);
    return lines.slice(-limit).map((l) => JSON.parse(l) as TurnEvent);
  } catch {
    return [];
  }
},

function isVerboseEnabled(): boolean {
  const value = process.env.MATRIXCORE_LOG ?? "";
  return value.toLowerCase() === "debug" || value.toLowerCase() === "verbose";
}

function verboseLogRoot(root: string): string {
  return path.join(root, ".quality", "verbose.log");
}

function appendVerboseLog(root: string, line: string): void {
  if (!isVerboseEnabled()) return;
  const full = `${new Date().toISOString()} [DEBUG] ${line}`;
  try {
    fs.mkdirSync(path.join(root, ".quality"), { recursive: true });
    fs.appendFileSync(verboseLogRoot(root), `${full}\n`);
  } catch {}
