  } catch {}
}

function verboseEnabled(): boolean {
  return isVerboseEnabled();
}

function gitIndexFingerprint(root: string): string {
  const entries = runGit(["ls-files", "--stage", "-z"], root);
  return hashBytes(Buffer.from(entries, "utf8"));
}

function hashBytes(buf: Buffer): string {
  return crypto.createHash("sha256").update(buf).digest("hex");
}

function hashPolicy(root: string): string {
  try {
    const resolved = resolveConfig({ cwd: root });
    const policy = resolvePolicyForConfig(resolved);
    return policy.policyHash;
  } catch {
    return "";
  }
}

function gitEntries(root: string): VersionEntry[] {
  const raw = runGit(["status", "--porcelain", "-z", "--untracked-files=all"], root);
  const entries: VersionEntry[] = [];
  if (!raw) return entries;
  const tokens = raw.split("\0");
  for (let i = 0; i < tokens.length; i++) {
    const tok = tokens[i];
    if (!tok) continue;
    if (tok.length < 4) continue;
    const xy = tok.slice(0, 2);
    const rel = tok.slice(3);
    if (!rel) continue;
    if (rel === ".quality" || rel.startsWith(".quality/")) continue;
    const abs = path.join(root, rel);
    const state = xy.trim() || "??";
    entries.push({ path: rel, state, hash: state === "D" ? "" : hashFile(abs) });
    if ((xy[0] === "R" || xy[0] === "C") && tokens[i + 1]) i += 1;
  }
  return entries;
}

function normalizedMode(value: unknown): string | null {
  return typeof value === "string" ? value.trim().toLowerCase() : null;
}

function getPayloadValue(payload: VendorPayload, ...keys: string[]): unknown {
  for (const key of keys) {
    if (key in payload) return payload[key];
  }
  return undefined;
}

isPlanMode(payload: VendorPayload): boolean {
  if (normalizedMode(getPayloadValue(payload, "permissionMode", "permission_mode")) === "plan") return true;
  return false;
},

resolveRoot(payload: VendorPayload): string {
  const cwd = getPayloadValue(payload, "cwd") as string | undefined;
  if (cwd) return resolveConfig({ cwd }).configRoot;
  throw new Error("Cannot resolve workspace root from Claude payload");
},

onToolCall(payload: VendorPayload): AdapterEvent | null {
  return { type: "DIRTY", payload };
},

onTurnStart(payload: VendorPayload): AdapterEvent | null {
  return { type: "DIRTY", payload };
},

onTurnEnd(payload: VendorPayload): AdapterEvent | null {
  return { type: "CANDIDATE_COMPLETE", payload };
},

getBackgroundTasks(_payload: VendorPayload): string[] | null {
  return null;
},

isPlanMode(payload: VendorPayload): boolean {
  if (normalizedMode(getPayloadValue(payload, "permissionMode", "permission_mode")) === "plan") return true;
  return false;
},

function codexTranscriptReportsPlan(payload: VendorPayload): boolean {
  const transcriptPath = getPayloadValue(payload, "transcriptPath", "transcript_path") as string | undefined;
  const turnId = getPayloadValue(payload, "turnId", "turn_id") as string | undefined;
  if (!transcriptPath || !turnId || typeof transcriptPath !== "string" || typeof turnId !== "string") return false;

  try {
    if (!fs.existsSync(transcriptPath)) return false;
    const content = fs.readFileSync(transcriptPath, "utf8");
    let foundPlan = false;
    for (const line of content.split("\n")) {
      if (!line.trim()) continue;
      try {
        const record = JSON.parse(line);
        if (record.type !== "event_msg" || !record.payload) continue;
        const eventPayload = record.payload as Record<string, unknown>;
        if (eventPayload.type !== "task_started" || eventPayload.turn_id !== turnId) continue;
        const collabMode = eventPayload.collaboration_mode_kind;
        if (normalizedMode(collabMode) === "plan") {
          foundPlan = true;
        } else {
          foundPlan = false;
        }
      } catch {}
    }
    return foundPlan;
  } catch {}
  return false;
}

isPlanMode(payload: VendorPayload): boolean {
  if (normalizedMode(getPayloadValue(payload, "permissionMode", "permission_mode")) === "plan") return true;
  if (normalizedMode(getPayloadValue(payload, "collaborationModeKind", "collaboration_mode_kind")) === "plan")
    return true;
  return codexTranscriptReportsPlan(payload);
},

export function getAdapter(host: string): VendorAdapter | null {
  return adapters[host] ?? null;
}

export function listAdapters(): VendorAdapter[] {
  return Object.values(adapters);
}

export function processTurnEnd(host: string, payload: VendorPayload): AdapterEvent | null {
  const adapter = getAdapter(host);
  if (!adapter) return null;
  if (adapter.isPlanMode(payload)) return { type: "PLAN_MODE", payload };
  return adapter.onTurnEnd(payload);
}

async function readStdin(): Promise<string> {
  const chunks: Buffer[] = [];
  for await (const chunk of process.stdin) chunks.push(Buffer.from(chunk));
  return Buffer.concat(chunks).toString("utf8");
}

function hasValidationRelevantBackgroundTasks(tasks: string[] | null): boolean {
  if (!tasks || tasks.length === 0) return false;
  const relevant = ["test", "build", "lint", "typecheck", "generate", "migrate"];
  return tasks.some((t) => relevant.some((r) => t.toLowerCase().includes(r)));
}

export async function renderHookDecision(host: HookHost, payload: Record<string, unknown>) {
  const adapter = getAdapter(host);
  if (!adapter) {
    return host === "cline"
      ? { cancel: true, errorMessage: `Unknown host: ${host}` }
      : { decision: "block", reason: `Unknown host: ${host}` };
  }

  if (adapter.isPlanMode(payload as any)) {
    return host === "cline" ? { cancel: false, contextModification: "", errorMessage: "" } : {};
  }

  let root: string;
  try {
    root = resolveRoot(host, payload as any);
    recordEngineRuntime(root, "hook");
  } catch (error) {
    const reason = `MatrixCore completion hook failed: ${error instanceof Error ? error.message : String(error)}`;
    return host === "cline"
      ? { cancel: true, contextModification: "", errorMessage: reason }
      : { decision: "block", reason };
  }

  const turnGate = new TurnGate(root);

  // Handle markDirty event (for tool calls, turn_start, etc. - doesn't block)
  if (payload.event === "markDirty") {
    turnGate.onDirty(host, getTurnId(payload));
    return host === "cline" ? { cancel: false, contextModification: "", errorMessage: "" } : {};
  }

  const bgTasks = getBackgroundTasks(host, payload as any);
  if (bgTasks && hasValidationRelevantBackgroundTasks(bgTasks)) {
    const reason = `Validation-relevant background tasks running: ${bgTasks.join(", ")}. Wait for completion.`;
    return host === "cline"
      ? { cancel: true, contextModification: "", errorMessage: reason }
      : { decision: "block", reason };
  }

  const turnEndEvent = processTurnEnd(host, payload as any);
  if (!turnEndEvent) {
    return host === "cline" ? { cancel: false, contextModification: "", errorMessage: "" } : {};
  }

  if (turnEndEvent.type === "PLAN_MODE") {
    return host === "cline" ? { cancel: false, contextModification: "", errorMessage: "" } : {};
  }

  let result;
  try {
    result = await turnGate.onCandidateComplete(host, getTurnId(payload));
  } catch (error) {
    turnStore.failed(root, error instanceof Error ? error.message : String(error), host, getTurnId(payload));
    const reason = `MatrixCore validation infrastructure failed: ${error instanceof Error ? error.message : String(error)}`;
    return host === "cline"
      ? { cancel: true, contextModification: reason, errorMessage: reason }
      : { decision: "error", reason };
  }

  if (result.decision === "allow") {
    return host === "cline" ? { cancel: false, contextModification: "", errorMessage: "" } : {};
  }

  if (result.decision === "error") {
    return host === "cline"
      ? { cancel: true, contextModification: result.reason, errorMessage: result.reason }
      : { decision: "error", reason: result.reason };
  }

  return host === "cline"
    ? { cancel: true, contextModification: result.reason, errorMessage: result.reason }
    : { decision: "block", reason: result.reason };
}

function isMainModule(): boolean {
  if (!process.argv[1]) return false;
  try {
    return fs.realpathSync(fileURLToPath(import.meta.url)) === fs.realpathSync(path.resolve(process.argv[1]));
  } catch {
    return false;
  }
}

async function main() {
  const host = process.argv[2] as HookHost;
  const event = process.argv[3] || "turn_end";
  if (!(["cline", "codex", "claude"] as string[]).includes(host)) {
    throw new Error("Usage: matrixcore-hook <cline|codex|claude> <event>");
  }
  const raw = await readStdin();
  const payload = JSON.parse(raw || "{}") as Record<string, unknown>;
  payload.event = event;
  const decision = await renderHookDecision(host, payload);
  process.stdout.write(`${JSON.stringify(decision)}\n`);
}

export function createMatrixCoreMcpServer() {
  const server = new McpServer({ name: "matrix-core", version: ENGINE_VERSION });
  const root = z.string().optional().describe("Workspace root; defaults to host workspace metadata or process cwd");
  server.registerTool(
    "quality_run",
    {
      description:
        "Run centrally owned deterministic checks, an explicit review, or the completion workflow. Completion includes advisory AgentSmith when the project enables it.",
      inputSchema: {
        root,
        mode: z.enum(["changed", "full", "review", "completion"]).default("full"),
        fast: z.boolean().optional(),
        base: z.string().optional(),
      },
    },
    async (input, extra) => call("quality_run", input, extra.signal),
  );
  server.registerTool(
    "quality_status",
    {
      description: "Read the current versioned deterministic gate and advisory review without running checks.",
      inputSchema: { root },
    },
    async (input, extra) => call("quality_status", input, extra.signal),
  );
  server.registerTool(
    "graph_status",
    {
      description: "Ensure the repository graph is ready and return its snapshot identity.",
      inputSchema: { root },
    },
    async (input, extra) => call("graph_status", input, extra.signal),
  );
  server.registerTool(
    "quality_fix",
    {
      description:
        "Prepare a version-bound repair task. This never invokes Ollama or edits code; the active host model applies the returned task.",
      inputSchema: {
        root,
        review_version: z.string(),
        finding_ids: z.array(z.string()).min(1),
      },
    },
    async (input, extra) => call("quality_fix", input, extra.signal),
  );
  return server;
}

export async function startMatrixCoreMcpServer(options?: {
  stdin?: Readable;
  stdout?: Writable;
  installSignalHandlers?: boolean;
}) {
  const server = createMatrixCoreMcpServer();
  const stdin = options?.stdin ?? process.stdin;
  const stdout = options?.stdout ?? process.stdout;
  const transport = new StdioServerTransport(stdin, stdout);
  let closing: Promise<void> | null = null;
  const close = () => {
    if (closing) return closing;
    closing = (async () => {
      stdin.off("end", onInputClosed);
      stdin.off("close", onInputClosed);
      process.off("SIGINT", onSignal);
      process.off("SIGTERM", onSignal);
      try {
        await server.close();
      } finally {
        cleanupMcpRuntimeRecords();
      }
    })();
    return closing;
  };
  const onInputClosed = () => void close();
  const onSignal = () => void close();
  stdin.once("end", onInputClosed);
  stdin.once("close", onInputClosed);
  if (options?.installSignalHandlers !== false) {
    process.once("SIGINT", onSignal);
    process.once("SIGTERM", onSignal);
  }
  await server.connect(transport);
  return { server, transport, close };
}

const close = () => {
  if (closing) return closing;
  closing = (async () => {
    stdin.off("end", onInputClosed);
    stdin.off("close", onInputClosed);
    process.off("SIGINT", onSignal);
    process.off("SIGTERM", onSignal);
    try {
      await server.close();
    } finally {
      cleanupMcpRuntimeRecords();
    }
  })();
  return closing;
};

async function main() {
  await startMatrixCoreMcpServer();
}

