async run(ctx: RunCtx, caps: Map<string, Capability>): Promise<PluginResult> {
  const cap = caps.get("golangci-lint") || caps.get("go.golangci") || caps.get("golangci");
  if (!cap || !cap.found) {
    const req = cap?.required ?? false;
    return {
      plugin: "go.golangci",
      status: req ? "FAIL" : "SKIPPED",
      observations: [{ message: "golangci-lint not found", severity: req ? "error" : "info" }],
      metrics: { "go.golangci.error_count": null, "golangci.error_count": null },
      reason: req ? "not found but required=true" : "not found, required=false",
    };
  }
  if (!ctx.full && ctx.changedFiles) {
    const hasGo = ctx.changedFiles.some((f) => f.endsWith(".go"));
    if (!hasGo)
      return {
        plugin: "go.golangci",
        status: "PASS",
        observations: [],
        metrics: { "go.golangci.error_count": 0, "golangci.error_count": 0 },
        score: 100,
        reason: "no go files changed",
      };
  }
  try {
    const args = ["run", "--out-format", "json", "./..."];
    if (verboseEnabled()) {
      console.debug(`[matrix-core] golangci-lint argv: golangci-lint ${args.join(" ")}`);
    }
    const res = spawnSync("golangci-lint", args, {
      cwd: ctx.root,
      encoding: "utf8",
      timeout: 120000,
    });
    if (verboseEnabled()) {
      console.debug(
        `[matrix-core] golangci-lint exit=${res.status} stdout=${(res.stdout || "").slice(0, 500)} stderr=${(res.stderr || "").slice(0, 500)}`,
      );
    }
    let errorCount = 0;
    const obs: Observation[] = [];
    try {
      const data = res.stdout ? JSON.parse(res.stdout) : { Issues: [] };
      const issues = data.Issues || [];
      errorCount = issues.length;
      for (const iss of issues.slice(0, 100)) {
        obs.push({
          file: iss.Pos?.Filename,
          line: iss.Pos?.Line,
          message: iss.Text,
          severity: "error",
          ruleId: iss.FromLinter,
        });
      }
    } catch {
      errorCount = res.status !== 0 ? 1 : 0;
      if (res.stdout) obs.push({ message: res.stdout.slice(0, 5000), severity: "error" });
    }
    return {
      plugin: "go.golangci",
      status: errorCount > 0 ? "FAIL" : "PASS",
      score: errorCount === 0 ? 100 : Math.max(0, 100 - errorCount),
      observations: obs,
      metrics: { "go.golangci.error_count": errorCount, "golangci.error_count": errorCount },
      reason: errorCount > 0 ? `${errorCount} issues` : undefined,
    };
  } catch (e: any) {
    return {
      plugin: "go.golangci",
      status: "ERROR",
      observations: [{ message: e.message, severity: "error" }],
      metrics: { "go.golangci.error_count": null },
      reason: "exception",
    };
  }
},

function tryTsc(
  root: string,
  args: string[],
  designated?: string,
): { stdout: string; stderr: string; status: number | null } {
  const local = designated ?? path.join(root, "node_modules", ".bin", "tsc");
  const candidates: Array<[string, string[]]> = [[local, args]];
  for (const [bin, a] of candidates) {
    if (verboseEnabled()) {
      console.debug(`[matrix-core] tsc argv: ${bin} ${a.join(" ")}`);
    }
    try {
      const res = spawnSync(bin, a, { cwd: root, encoding: "utf8", timeout: 60000, env: childProcessEnv() });
      if (verboseEnabled()) {
        console.debug(
          `[matrix-core] tsc exit=${res.status} stdout=${(res.stdout || "").slice(0, 500)} stderr=${(res.stderr || "").slice(0, 500)}`,
        );
      }
      if (res.error) {
        const error = res.error as NodeJS.ErrnoException;
        return { stdout: res.stdout || "", stderr: `${error.code ?? "spawn"}: ${error.message}`, status: null };
      }
      if (res.status !== null) return { stdout: res.stdout || "", stderr: res.stderr || "", status: res.status };
    } catch {}
  }
  return { stdout: "", stderr: "tsc not found", status: null };
}

function runVitest(root: string, extra: string[]): { stdout: string; stderr: string; status: number | null } {
  const local = path.join(root, "node_modules", ".bin", "vitest");
  const candidates: Array<[string, string[]]> = [
    [local, ["run", "--reporter=json", ...extra]],
    ["vitest", ["run", "--reporter=json", ...extra]],
    ["npx", ["--no-install", "vitest", "run", "--reporter=json", ...extra]],
  ];
  for (const [bin, a] of candidates) {
    if (verboseEnabled()) {
      console.debug(`[matrix-core] vitest argv: ${bin} ${a.join(" ")}`);
    }
    try {
      const res = spawnSync(bin, a, { cwd: root, encoding: "utf8", timeout: 120000, env: childProcessEnv() });
      if (verboseEnabled()) {
        console.debug(
          `[matrix-core] vitest exit=${res.status} stdout=${(res.stdout || "").slice(0, 500)} stderr=${(res.stderr || "").slice(0, 500)}`,
        );
      }
      if (res.error) continue;
      if (res.status !== null) return { stdout: res.stdout || "", stderr: res.stderr || "", status: res.status };
    } catch {}
  }
  return { stdout: "", stderr: "vitest not found", status: null };
}

function makeProvider(opts: {
  candidatesPerCall?: number;
  holisticCandidates?: number;
  candidateDelayMs?: number;
  verificationDelayMs?: number;
  blockCandidates?: boolean;
  blockVerification?: boolean;
  blockScout?: boolean;
  firstVerificationVerified?: boolean;
  scoutHotspots?: unknown[];
  malformedCandidate?: boolean;
}): ProviderHarness {
  const calls: CallKind[] = [];
  const state: ProviderHarness = {
    provider: null as never,
    calls,
    candidatePrompts: [],
    candidateLimits: [],
    maxActive: 0,
    invokedAfterAbort: 0,
  };
  let candidateCall = 0;
  let verificationCall = 0;
  let active = 0;
  const fileFromPrompt = (prompt: string) => /--- ([^:\s]+):/.exec(prompt)?.[1] ?? "unknown.ts";
  function candidatePayload(file: string, index: number) {
    return {
      f: file,
      l: 1,
      s: "high" as const,
      k: "correctness" as const,
      t: `Probe defect ${index}`,
      d: `Changed value at ${file} causes a concrete failure for probe index ${index}.`,
      g: "Guard the value.",
      q: 0.9,
      e: [],
    };
  }
  state.provider = {
    health: async () => ({ ok: true, models: ["qwen3.5:9b-q4_K_M", "qwen3.5:122b-a10b"] }),
    invoke: async (input) => {
      calls.push(input.outputKind);
      if (input.signal?.aborted) state.invokedAfterAbort++;
      active++;
      state.maxActive = Math.max(state.maxActive, active);
      try {
        if (input.outputKind === "scout") {
          if (opts.blockScout) await waitForAbort(input.signal);
          if (opts.candidateDelayMs) await delay(opts.candidateDelayMs);
          return {
            raw: JSON.stringify({ hotspots: opts.scoutHotspots ?? [] }),
            usage: { inputTokens: 10, outputTokens: 5 },
          };
        }
        if (input.outputKind === "verification") {
          if (opts.verificationDelayMs) await delay(opts.verificationDelayMs);
          if (opts.blockVerification) await waitForAbort(input.signal);
          if (opts.firstVerificationVerified && verificationCall++ > 0) await waitForAbort(input.signal);
          return {
            raw: '{"verdict":"verified","confidence":1,"supportingEvidenceIds":[]}',
            usage: { inputTokens: 10, outputTokens: 5 },
          };
        }
        if (opts.blockCandidates) await waitForAbort(input.signal);
        state.candidatePrompts.push(input.prompt);
        state.candidateLimits.push(input.maxCandidates);
        if (opts.candidateDelayMs) await delay(opts.candidateDelayMs);
        if (opts.malformedCandidate)
          return {
            raw: '{"c":[{"d":"unfinished',
            usage: { inputTokens: 12, outputTokens: 4096 },
            completion: {
              model: "qwen3.5:9b-q4_K_M",
              done: true,
              doneReason: "length",
              totalDurationNs: 64_000_000_000,
              loadDurationNs: 1_000_000,
              promptEvalDurationNs: 2_000_000,
              evalDurationNs: 63_000_000_000,
            },
          };
        const file = fileFromPrompt(input.prompt);
        const count = opts.holisticCandidates ?? opts.candidatesPerCall ?? 1;
        const candidates = Array.from({ length: count }, (_, index) =>
          candidatePayload(file, candidateCall * 100 + index),
        );
        candidateCall++;
        return {
          raw: JSON.stringify({ c: candidates }),
          usage: { inputTokens: 10, outputTokens: 5 },
        };
      } finally {
        active--;
      }
    },
  };
  return state;
}

