export async function executeQualityTool(
  name: QualityToolName,
  input: QualityToolInput,
  signal?: AbortSignal,
): Promise<unknown> {
  const root = resolveToolRoot(input.root);
  recordEngineRuntime(root, "mcp");
  if (signal?.aborted) throw signal.reason ?? new Error("MatrixCore operation cancelled");
  if (name === "graph_status") return repositoryGraph(root).ensureReady();
  if (name === "quality_status") return getQualityStatus(root);
  if (name === "quality_fix")
    return prepareFix({
      cwd: root,
      reviewVersion: input.review_version ?? "",
      findingIds: input.finding_ids ?? [],
    });
  const mode = input.mode ?? "full";
  if (mode === "completion") {
    const completion = await runQualityCompletion({
      cwd: root,
      mode: "full",
      fast: false,
      base: input.base,
      tool: "quality_run",
      adapter: "mcp",
      signal,
    });
    return completion;
  }
  if (mode === "review")
    return runQualityReview({
      cwd: root,
      mode: "full",
      fast: input.fast,
      base: input.base,
      tool: "quality_run",
      adapter: "mcp",
      signal,
    });
  const gate = await runGate({
    cwd: root,
    mode,
    fast: input.fast,
    base: input.base,
    tool: "quality_run",
    adapter: "mcp",
    signal,
  });
  if (gate.mode === "full" && !gate.fast) {
    turnStore.recordGateResult(root, gate, gate.status === "PASS" ? "PASS" : "REJECT", "mcp");
  }
  return gate;
}

