function runRuff(
  root: string,
  targets: string[] | undefined,
  extra: string[],
  binary = "ruff",
): { violations: any[]; error?: string } {
  const args = ["check", "--output-format", "json", ...(extra as string[]), ...(targets || ["."])];
  if (verboseEnabled()) {
    console.debug(`[matrix-core] ruff argv: ${binary} ${args.join(" ")}`);
  }
  const res = spawnSync(binary, args, { cwd: root, encoding: "utf8", timeout: 30000 });
  if (verboseEnabled()) {
    console.debug(
      `[matrix-core] ruff exit=${res.status} stdout=${(res.stdout || "").slice(0, 500)} stderr=${(res.stderr || "").slice(0, 500)}`,
    );
  }
  if (res.status === null && !res.stdout)
    return { violations: [], error: `ruff execution failed: ${res.stderr?.slice(0, 2000)}` };
  let violations: any[] = [];
  try {
    const t = (res.stdout || "").trim();
    if (t) {
      const p = JSON.parse(t);
      if (Array.isArray(p)) violations = p;
    }
  } catch {
    violations = [];
  }
  return { violations };
}

function observations(output: string, root: string): Observation[] {
  return output
    .split(/\r?\n/)
    .map((line) => line.trim())
    .filter(Boolean)
    .map((message) => {
      const location = message.match(/["']?([^"']+\.py):(\d+)(?::(\d+))?/);
      const file = location?.[1];
      return {
        file: file ? (path.isAbsolute(file) ? path.relative(root, file) : file) : undefined,
        line: location ? Number(location[2]) : undefined,
        col: location?.[3] ? Number(location[3]) : undefined,
        message,
        severity: "error" as const,
        ruleId: "complexity",
      };
    });
}

