function tryEslint(
  root: string,
  files: string[] | undefined,
  extra: string[],
  designated?: string,
): { stdout: string; status: number | null; error?: string } {
  const targets = files && files.length > 0 ? files : ["."];
  const maxWarnings = extra.some((a) => a.includes("max-warnings")) ? [] : ["--max-warnings", "0"];
  const noWarnIgnored = extra.some((a) => a.includes("no-warn-ignored")) ? [] : ["--no-warn-ignored"];
  const args = [...extra, ...maxWarnings, ...noWarnIgnored, "--format", "json", ...targets];
  const local = designated ?? path.join(root, "node_modules", ".bin", "eslint");
  const candidates: Array<[string, string[]]> = [[local, args]];
  for (const [bin, a] of candidates) {
    if (verboseEnabled()) {
      console.debug(`[matrix-core] eslint argv: ${bin} ${a.join(" ")}`);
    }
    try {
      const res = spawnSync(bin, a, { cwd: root, encoding: "utf8", timeout: 60000, env: childProcessEnv() });
      if (verboseEnabled()) {
        console.debug(
          `[matrix-core] eslint exit=${res.status} stdout=${(res.stdout || "").slice(0, 500)} stderr=${(res.stderr || "").slice(0, 500)}`,
        );
      }
      if (res.error) {
        const error = res.error as NodeJS.ErrnoException;
        return { stdout: res.stdout || "", status: null, error: `${error.code ?? "spawn"}: ${error.message}` };
      }
      if (res.status !== null) return { stdout: res.stdout || "", status: res.status };
    } catch {}
  }
  return { stdout: "", status: null, error: "eslint not found" };
}

function parseEslint(stdout: string): { errorCount: number; warnings: number; obs: Observation[]; parsed: boolean } {
  let errorCount = 0;
  let warnings = 0;
  let parsed = false;
  const obs: Observation[] = [];
  const t = (stdout || "").trim();
  if (t) {
    try {
      const json = JSON.parse(t);
      if (!Array.isArray(json)) return { errorCount: 0, warnings: 0, obs: [], parsed: false };
      parsed = true;
      for (const file of json as any[]) {
        for (const msg of file.messages || []) {
          if (msg.severity === 2) errorCount++;
          else if (msg.severity === 1) warnings++;
          obs.push({
            file: file.filePath,
            line: msg.line,
            col: msg.column,
            message: msg.message,
            severity: msg.severity === 2 ? "error" : "warn",
            ruleId: msg.ruleId,
          });
        }
      }
    } catch {
      return { errorCount: 0, warnings: 0, obs: [], parsed: false };
    }
  }
  return { errorCount, warnings, obs, parsed };
}

function tryPrettier(
  root: string,
  files: string[] | undefined,
  extra: string[],
): { files: string[]; status: number | null } {
  const targets = files && files.length > 0 ? files : ["."];
  const args = [...extra, "--check", ...targets];
  const local = path.join(root, "node_modules", ".bin", "prettier");
  const candidates: Array<[string, string[]]> = [
    [local, args],
    ["prettier", args],
    ["npx", ["--no-install", "prettier", ...args]],
  ];
  for (const [bin, a] of candidates) {
    if (verboseEnabled()) {
      console.debug(`[matrix-core] prettier argv: ${bin} ${a.join(" ")}`);
    }
    try {
      const res = spawnSync(bin, a, { cwd: root, encoding: "utf8", timeout: 60000, env: childProcessEnv() });
      if (verboseEnabled()) {
        console.debug(
          `[matrix-core] prettier exit=${res.status} stdout=${(res.stdout || "").slice(0, 500)} stderr=${(res.stderr || "").slice(0, 500)}`,
        );
      }
      if (res.error) continue;
      if (res.status !== null) {
        const out = (res.stdout || "") + "\n" + (res.stderr || "");
        const flagged = new Set<string>();
        for (const line of out.split("\n")) {
          if (!line.startsWith("[warn] ")) continue;
          const f = line.slice("[warn] ".length).trim();
          if (!f || f.includes("Code style") || f.includes("Run Prettier") || f.includes("Forgot to run Prettier"))
            continue;
          flagged.add(f);
        }
        return { files: [...flagged], status: res.status };
      }
    } catch {}
  }
  return { files: [], status: null };
}

