export function processEvent(host: string, payload: VendorPayload): AdapterEvent[] {
  const adapter = getAdapter(host);
  if (!adapter) return [];

  const events: AdapterEvent[] = [];

  if (adapter.isPlanMode(payload)) {
    events.push({ type: "PLAN_MODE", payload });
    return events;
  }

  const dirty = adapter.onToolCall(payload);
  if (dirty) events.push(dirty);

  return events;
}

export function processTurnStart(host: string, payload: VendorPayload): AdapterEvent | null {
  const adapter = getAdapter(host);
  if (!adapter) return null;
  if (adapter.isPlanMode(payload)) return { type: "PLAN_MODE", payload };
  return adapter.onTurnStart(payload);
}

export function getBackgroundTasks(host: string, payload: VendorPayload): string[] | null {
  const adapter = getAdapter(host);
  if (!adapter) return null;
  return adapter.getBackgroundTasks(payload);
}

export function resolveRoot(host: string, payload: VendorPayload): string {
  const adapter = getAdapter(host);
  if (!adapter) throw new Error(`Unknown host: ${host}`);
  return adapter.resolveRoot(payload);
}

function getTurnId(payload: Record<string, unknown>): string | undefined {
  const value = payload.turn_id ?? payload.turnId;
  return typeof value === "string" && value.length > 0 ? value : undefined;
}

export const golangciPlugin: QualityPlugin = {
  name: "go.golangci",
  pack: "go",
  aliases: ["golangci-lint", "golangci"],
  async run(ctx: RunCtx, caps: Map<string, Capability>): Promise<PluginResult> {
    const cap = caps.get("golangci-lint") || caps.get("go.golangci") || caps.get("golangci");
    if (!cap || !cap.found) {
      const req = cap?.required ?? false;
      return {
        plugin: "go.golangci",
        status: req ? "FAIL" : "SKIPPED",
        observations: [{ message: "golangci-lint not found", severity: req ? "error" : "info" }],
        metrics: { "go.golangci.error_count": null, "golangci.error_count": null },
        reason: req ? "not found but required=true" : "not found, required=false",
      };
    }
    if (!ctx.full && ctx.changedFiles) {
      const hasGo = ctx.changedFiles.some((f) => f.endsWith(".go"));
      if (!hasGo)
        return {
          plugin: "go.golangci",
          status: "PASS",
          observations: [],
