function record(
  request: EvidenceRequest,
  file: string,
  startLine: number,
  lines: string[],
  symbol?: string,
  relation?: string,
): EvidenceRecord {
  const snippet = lines.join("\n");
  const id = crypto
    .createHash("sha256")
    .update(JSON.stringify({ request, file, startLine, snippet, symbol, relation }))
    .digest("hex")
    .slice(0, 16);
  return {
    id,
    requestKind: request.kind,
    file,
    startLine,
    endLine: startLine + lines.length - 1,
    symbol,
    snippet,
    relation,
  };
}

function runGit(args: string[], cwd: string): string {
  try {
    const res = spawnSync("git", args, { cwd, encoding: "utf8", timeout: 8000 });
    if (res.error || res.status !== 0) return "";
    return (res.stdout || "").trim();
  } catch {
    return "";
  }
}

function hashConfig(root: string): string {
  const configPath = path.join(root, "quality.yaml");
  if (!fs.existsSync(configPath)) return "";
  try {
    const content = fs.readFileSync(configPath, "utf8");
    return crypto.createHash("sha256").update(content).digest("hex").slice(0, 16);
  } catch {
    return "";
  }
}

